// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Para, bankacılık, enflasyon, faiz ve kişisel finans (orta).
const ozEconomics2Orta = <(String, String, List<String>, String)>[
  ('Yıllık enflasyonun yüzde 80 olduğu bir ülkede insanlar tasarruflarını ulusal parada tutmak yerine başka varlıklara yöneliyorsa paranın hangi işlevi en çok zarar görmüştür?', 'Değer saklama işlevi', ['Hesap birimi olma işlevi', 'Değişim aracı olma işlevi', 'Basılabilir olma işlevi'], 'Yüksek enflasyon paranın satın alma gücünü hızla eritir; bu nedenle para zaman içinde değeri koruma (değer saklama) işlevini en çok yitirir.'),
  ('Aşağıdakilerden hangisi bir nesnenin iyi bir para olabilmesi için taşıması gereken özelliklerden biri değildir?', 'Kolayca çoğaltılabilmesi', ['Bölünebilir olması', 'Dayanıklı olması', 'Kolay taşınabilir ve saklanabilir olması'], 'İyi bir paranın kıt olması gerekir; herkesin kolayca çoğaltabildiği bir nesne değerini korumaz. Bölünebilirlik, dayanıklılık ve taşınabilirlik ise aranan özelliklerdir.'),
  ('Bir ekonomist, sigaraların savaş esiri kamplarında para gibi kullanıldığını anlatıyor. Bu örnek en çok hangi görüşü destekler?', 'Toplumun kabul ettiği her nesne para işlevi görebilir', ['Para ancak devlet basarsa para sayılır', 'Para yalnızca değerli metalden yapılabilir', 'Bir nesnenin para işlevi görebilmesi için faiz getirmesi gerekir'], 'Para işlevini belirleyen şey genel kabul görmesidir; kamplarda sigaranın değişim aracı olarak kullanılması bunun bilinen bir örneğidir.'),
  ('Paranın hesap birimi işlevi takas ekonomisine göre hangi kolaylığı sağlar?', 'Her malın tek bir fiyatla ifade edilmesiyle karşılaştırma sayısını azaltır', ['Her malın üretim maliyetini sıfıra indirir ve böylece fiyatları ortadan kaldırarak takası gereksiz kılar', 'Mal arzını kendiliğinden artırır', 'Bütün malların fiyatlarını eşitler'], 'Takasta her mal çifti için ayrı bir değişim oranı gerekir; ortak hesap birimiyle her mal tek bir fiyatla ifade edilir ve karşılaştırma büyük ölçüde kolaylaşır.'),
  ('Altın standardı döneminde banknot sahibinin bankaya giderek kâğıt parasını belirli miktar altınla değiştirebilmesi bu paranın hangi niteliğini gösterir?', 'Temsili para olduğunu', ['Kaydi para olduğunu', 'Mal para olduğunu', 'İtibari (fiat) para olduğunu'], 'Altın standardında kâğıt para belirli bir altın miktarını temsil eder ve istendiğinde altına çevrilebilir; bu tür paraya temsili para denir.'),
  ('Gresham yasası "kötü para iyi parayı piyasadan kovar" der. Hangi durum bu yasaya örnektir?', 'Gümüş oranı yüksek eski sikkelerin saklanıp düşük ayarlı yenilerin harcanması', ['Kâğıt paranın her yerde madeni paradan daha çok sevilmesi ve sikkelerin hiç kullanılmaması', 'Bankaların mevduata faiz ödemesi', 'Enflasyonun düşük olduğu dönemde tasarrufun artması'], 'Aynı itibari değere sahip iki paradan metal değeri yüksek olan saklanır, düşük olan dolaşımda kalır; Gresham yasası budur.'),
  ('Madeni paraların kenarlarına tırtıl açılmasının tarihsel amacı neydi?', 'Kenarlardan metal kazınarak değerinin çalınmasını önlemek', ['Paranın masada ya da yerde daha hızlı yuvarlanmasını sağlamak', 'Paraya faiz kazandırmak', 'Paranın renginin değişmesini önlemek'], 'Değerli metalden sikkelerin kenarı kazınıp metal çalınabiliyordu; tırtıllı kenar bu kırpmanın kolayca fark edilmesini sağladı.'),
  ('Rezerv para ya da parasal taban olarak adlandırılan büyüklük temel olarak neyi kapsar?', 'Dolaşımdaki para ile bankaların merkez bankasındaki rezervlerini', ['Bütün banka kredilerini', 'Borsada işlem gören bütün hisse senetlerinin toplam piyasa değerini', 'Hanehalkının toplam borcunu'], 'Parasal taban, merkez bankasının doğrudan yarattığı paradır: dolaşımdaki nakit ile bankaların merkez bankası nezdindeki rezervleri.'),
  ('Para tanımları M1\'den M3\'e doğru genişledikçe hangi özellik genel olarak azalır?', 'Likidite', ['Toplam tutar', 'Kapsanan araç sayısı', 'Hesaplanan kalem sayısı'], 'Geniş para tanımlarına eklenen kalemler nakde çevrilmesi daha zor araçlardır; bu yüzden tanım genişledikçe ortalama likidite azalır, toplam tutar ise artar.'),
  ('Paranın miktar teorisinin değişim denklemi hangisidir?', 'MV = PY', ['Y = C + I + G', 'P = MC', 'S = I'], 'Değişim denkleminde M para miktarı, V paranın dolaşım hızı, P fiyat düzeyi, Y reel üretimdir; MV = PY biçiminde yazılır.'),
  ('MV = PY denkleminde dolaşım hızı ve reel üretim sabitken para miktarı yüzde 10 artarsa fiyat düzeyi ne olur?', 'Yüzde 10 yükselir', ['Yüzde 10 düşer', 'Değişmeden kalır', 'Yüzde 20 oranında yükselir'], 'V ve Y sabitse P, M ile aynı oranda değişir; para miktarı yüzde 10 artınca fiyat düzeyi de yüzde 10 artar.'),
  ('Bir ekonomide para miktarı 500, dolaşım hızı 4 ve reel üretim 1.000 birimdir. Değişim denklemine göre fiyat düzeyi kaçtır?', '2', ['0,5', '8', '20'], 'MV = PY ise P = MV / Y = 500·4 / 1.000 = 2.'),
  ('Paranın dolaşım hızı kavramı neyi ifade eder?', 'Bir lira biriminin belirli sürede ortalama kaç kez el değiştirdiğini', ['Banknotların basılma hızını', 'Kur değişiminin günlük oranını', 'Bankaların bir kredi başvurusunu ortalama kaç günde onayladığını'], 'Dolaşım hızı, para stokunun bir dönemde nominal harcamaları finanse etmek için ortalama kaç kez kullanıldığını gösterir.'),
  ('Faiz oranlarının sıfıra çok yakın olduğu ve para arzı artışlarının harcamaları canlandıramadığı duruma ne ad verilir?', 'Likidite tuzağı', ['Para yanılsaması', 'Kalabalıklaştırma etkisi', 'Gresham yasası'], 'Likidite tuzağında faiz daha fazla düşemeyecek kadar düşüktür ve insanlar ek parayı harcamak yerine elde tutar; para politikası etkisizleşir.'),
  ('"Enflasyon her zaman ve her yerde parasal bir olgudur" sözüyle tanınan ekonomist kimdir?', 'Milton Friedman', ['John Maynard Keynes', 'David Ricardo', 'Karl Marx'], 'Bu söz, parasalcı (monetarist) okulun öncüsü Milton Friedman\'a aittir.'),
  ('Para yanılsaması kavramı hangi davranışı anlatır?', 'İnsanların reel yerine nominal değerlere bakarak karar vermesini', ['İnsanların alışverişlerde nakit yerine kart kullanmayı tercih etmesini', 'Bankaların sahte para basmasını', 'Merkez bankasının faiz kararını gizlemesini'], 'Para yanılsamasında kişi, örneğin yüzde 5 maaş artışını, enflasyon yüzde 8 olsa bile kazanç sanar; yani nominal rakamlara takılır.'),
  ('Merkez bankasının "son başvuru mercii" (son kredi verici) olması ne anlama gelir?', 'Likidite sıkıntısına düşen bankalara kriz anında kaynak sağlayabilmesi', ['Vatandaşlara doğrudan konut kredisi vermesi', 'Şirketlerin borsadaki hisse senetlerini satın almasının yasal zorunluluk olması', 'Vergi tahsil etme yetkisinin bulunması'], 'Bankalar geçici likidite sıkıntısına düştüğünde başka yerden kaynak bulamazsa merkez bankası onlara borç vererek sistemin çökmesini önler.'),
  ('Merkez bankası bağımsızlığının enflasyonla mücadelede önemli görülmesinin temel nedeni hangisidir?', 'Seçim dönemlerinde kısa vadeli siyasi baskıyla para basılmasını engellemesi', ['Merkez bankasının her yıl kâr etmesini ve hazineye kâr aktarmasını garanti etmesi', 'Bankaların kredi vermesini yasaklaması', 'Döviz kurunu sabit tutmayı zorunlu kılması'], 'Bağımsız bir merkez bankası, siyasi döngülerden etkilenmeden fiyat istikrarına odaklanabilir ve politikalarının inandırıcılığı artar.'),
  ('Bir merkez bankasının bütçe açığını kapatmak için hükümete sınırsız doğrudan kredi vermesi uzun vadede en çok hangi riski doğurur?', 'Para arzının denetimsiz artması ve yüksek enflasyon', ['Ülkede işsizliğin kendiliğinden sıfırlanması', 'Bankacılık sisteminde mevduat faizlerinin sürekli ve kalıcı olarak artması', 'Ulusal paranın kalıcı olarak değer kazanması'], 'Açıkların para basılarak finanse edilmesi para arzını hızla artırır; tarihte pek çok hiperenflasyon bu yolla ortaya çıkmıştır.'),
  ('Merkez bankalarının resmî rezervlerinde tuttuğu varlıklara örnek hangisidir?', 'Altın ve yabancı para cinsinden varlıklar', ['Hanelerin gayrimenkulleri', 'Şirketlerin stokları', 'Belediyelerin vatandaşlardan olan emlak vergisi alacakları'], 'Resmî rezervler, kur istikrarı ve dış ödemeler için tutulan altın ve döviz cinsinden varlıklardan oluşur.'),
  ('Merkez bankasının bankalar arası ödemelerin kesintisiz işlemesini sağlamak için ödeme sistemlerini işletmesi hangi amaca doğrudan hizmet eder?', 'Finansal istikrar', ['Vergi adaleti', 'Dış ticaret dengesi', 'Tarımsal üretim artışı'], 'Ödeme sistemlerinin güvenli çalışması, bir bankanın sorununun diğerlerine yayılmasını önler ve finansal istikrarı destekler.'),
  ('Bir ülkede enflasyon hedefin çok üzerindeyken merkez bankası hangi politika bileşimini uygularsa sıkı para politikası izlemiş olur?', 'Politika faizini artırıp açık piyasada tahvil satmak', ['Politika faizini düşürüp tahvil almak', 'Zorunlu karşılık oranını indirip aynı anda politika faizini düşürmek', 'Bankalara sınırsız ve faizsiz kredi açmak'], 'Faiz artışı ve tahvil satışı piyasadan likidite çeker; ikisi birlikte para politikasını sıkılaştırır.'),
  ('Para politikasının etkilerinin ekonomiye gecikmeli yansıdığı söylenir. Bunun en doğru yorumu hangisidir?', 'Faiz kararının enflasyona etkisi aylar hatta yıllar içinde ortaya çıkabilir', ['Faiz kararı aynı gün bütün fiyatları değiştirir', 'Para politikası yalnızca seçim yıllarında ekonomiyi etkileyebilen bir araçtır', 'Faiz kararları üretimi hiçbir zaman etkilemez'], 'Faiz değişikliği kredi, harcama ve beklentiler üzerinden yavaş yayılır; bu yüzden merkez bankaları ileriye dönük karar alır.'),
  ('Merkez bankasının politika faizini indirmesi mevduat sahibi bir emekliyi nasıl etkiler?', 'Mevduatından elde ettiği faiz geliri azalabilir', ['Mevduatının reel değeri kesinlikle ve kalıcı biçimde artar', 'Kredi kartı borcu faiz indirimiyle birlikte otomatik olarak silinir', 'Emekli maaşı yasa gereği artar'], 'Faiz indirimi bankaların mevduata verdiği faizi de düşürür; faiz geliriyle geçinen tasarrufçular için gelir kaybı doğar.'),
  ('Faizler sıfıra yakınken merkez bankasının büyük miktarda tahvil alarak uzun vadeli faizleri düşürmeye çalışmasına ne ad verilir?', 'Parasal genişleme', ['Sterilizasyon işlemleriyle likidite çekme', 'Devalüasyon', 'Mali kural'], 'Niceliksel genişlemede merkez bankası geniş çaplı varlık alımı yapar; amaç uzun vadeli faizleri düşürmek ve kredi koşullarını gevşetmektir.'),
  ('Merkez bankasının gelecekteki faiz patikası hakkında açıklamalar yaparak beklentileri yönetmesine ne denir?', 'İleriye dönük yönlendirme', ['Geriye dönük fiyat endekslemesi', 'Parasal taban daraltması', 'Kur sepeti ayarlaması'], 'İleriye dönük yönlendirmede merkez bankası faizlerin uzun süre belirli düzeyde kalacağını duyurarak piyasa beklentilerini etkiler.'),
  ('"Helikopter parası" benzetmesi hangi politika fikrini anlatır?', 'Doğrudan vatandaşlara para dağıtılarak harcamaların artırılmasını', ['Bankaların helikopterle nakit taşımasını', 'Faiz oranlarının her yıl kurala bağlı biçimde otomatik olarak yükseltilmesini', 'Altın rezervlerinin yurt dışına gönderilmesini'], 'Milton Friedman\'ın kullandığı benzetmede para, gökten saçılır gibi halka doğrudan verilir; bu yolla talebin canlandırılması amaçlanır.'),
  ('2005\'te kullanılmaya başlanan Yeni Türk Lirası adındaki "Yeni" ibaresi hangi yıl kaldırılmıştır?', '2009', ['2005', '2006', '2007'], '1 Ocak 2009\'dan itibaren "Yeni" ibaresi kaldırıldı ve para birimi yeniden Türk lirası adını aldı.'),
  ('Bir ülkenin parasından sıfır atılmasıyla ilgili aşağıdakilerden hangisi yanlıştır?', 'Ekonomideki reel satın alma gücünü artırır', ['Fiyatların yazılmasını kolaylaştırır', 'Muhasebe kayıtlarını sadeleştirir', 'Ödeme sistemlerinde ve fiyat etiketlerinde rakamları kısaltır'], 'Sıfır atmak bir ölçü birimi değişikliğidir; bütün fiyat ve gelirler aynı oranda bölündüğü için reel satın alma gücü değişmez.'),
  ('Bugün faaliyetini sürdüren en eski merkez bankası olarak bilinen kurum hangisidir?', 'İsveç Merkez Bankası (Riksbank)', ['ABD Merkez Bankası (Federal Rezerv)', 'Avrupa Merkez Bankası', 'Japonya Merkez Bankası'], 'İsveç\'in Riksbank\'ı 1668\'de kuruldu ve dünyanın hâlâ faaliyette olan en eski merkez bankası kabul edilir.'),
  ('ABD\'nin merkez bankası sistemi olan Federal Rezerv hangi yıl kurulmuştur?', '1913', ['1933', '1929', '1945'], 'Federal Rezerv Sistemi, 1913\'te Federal Rezerv Yasası ile kuruldu.'),
  ('Avro bölgesindeki bir ülke, ekonomisi durgunluktayken kendi başına faiz indiremez. Bunun nedeni hangisidir?', 'Para politikasının ortak merkez bankasınca bütün bölge için belirlenmesi', ['O ülkenin bankalarının faiz ödemesinin yasak olması', 'Avro bölgesinde faiz oranlarının bütün ülkelerin anayasalarıyla sabitlenmiş olması', 'Ülkenin kendi parasını basmaya devam etmesi'], 'Ortak para kullanan ülkeler para politikası yetkisini Avrupa Merkez Bankasına devretmiştir; tek bir ülkeye özgü faiz kararı alınamaz.'),
  ('İngiltere Merkez Bankası (Bank of England) hangi yüzyılda kurulmuştur?', '17. yüzyıl', ['15. yüzyıl', '19. yüzyıl', '20. yüzyıl'], 'Bank of England 1694\'te kuruldu; yani 17. yüzyılın sonunda faaliyete başladı.'),
  ('ABD Merkez Bankasının yasal görevi için kullanılan "ikili görev" ifadesi hangi iki hedefi anlatır?', 'Azami istihdam ve fiyat istikrarı', ['Dış ticaret fazlası ve düşük vergi', 'Borsa artışı ve sabit kur', 'Kamu borcunun sıfırlanması ve yüksek faiz'], 'Federal Rezerv\'in yasal görevi hem azami istihdamı hem de fiyat istikrarını gözetmektir; buna ikili görev denir.'),
  ('Bir ticari bankanın temel kâr kaynağı en doğru biçimde hangisiyle açıklanır?', 'Kredilere uyguladığı faiz ile mevduata ödediği faiz arasındaki fark', ['Merkez bankasından aldığı karşılıksız para basma yetkisi', 'Müşterilerinin vergi borçlarını tahsil edip elinde tutması', 'Borsadaki bütün hisse senetlerinin fiyatını tek başına belirleme yetkisine sahip olması'], 'Bankanın ana gelir kalemi net faiz gelirleridir: kredilerden alınan faiz ile mevduata ödenen faiz arasındaki fark (faiz marjı).'),
  ('Gerçek ekonomide para çarpanının basit formülün verdiğinden küçük çıkmasının bir nedeni hangisidir?', 'İnsanların paranın bir kısmını nakit olarak elde tutması', ['Bankaların kredilere hiç faiz uygulamaması', 'Merkez bankasının hiç banknot basmaması', 'Bütün kredilerin aynı gün ve tek seferde bankaya geri ödenmesi'], 'Halk paranın bir bölümünü nakit tutarsa bu para bankaya dönmez ve kredi zincirine katılmaz; bankaların fazla rezerv tutması da çarpanı küçültür.'),
  ('Bir banka zorunlu karşılığın üzerinde, kendi isteğiyle merkez bankasında tuttuğu rezervlere ne ad verilir?', 'Serbest (fazla) rezerv', ['Zorunlu karşılık rezervi', 'Ödenmiş sermaye', 'Takipteki alacak'], 'Zorunlu tutarın üzerinde kalan ve bankanın isteğe bağlı tuttuğu rezervler serbest ya da fazla rezerv olarak adlandırılır.'),
  ('Bir bankanın bilançosunda müşterilerin yatırdığı mevduat hangi tarafta yer alır?', 'Yükümlülükler (pasif) tarafında', ['Varlıklar (aktif) tarafında', 'Gelir tablosunda gelir olarak', 'Bilanço dışı taahhüt kalemleri arasında'], 'Mevduat bankanın müşterilerine borcudur; bu yüzden bilançonun yükümlülük (pasif) tarafındadır. Verilen krediler ise varlık tarafındadır.'),
  ('Bir bankanın verdiği kredilerin toplam mevduatına oranı neyi ölçer?', 'Mevduatın ne kadarının krediye dönüştürüldüğünü', ['Bankanın kaç şubesi olduğunu', 'Bankanın bir yılda devlete ödediği kurumlar vergisi miktarını', 'Merkez bankasının bir sonraki toplantıdaki faiz kararını'], 'Kredi/mevduat oranı bankanın topladığı kaynakları krediye ne ölçüde aktardığını gösterir; yüzde 100\'ün üzeri, kredilerin mevduat dışı kaynakla da finanse edildiğini gösterir.'),
  ('Yüksek enflasyon döneminde tasarrufunu vadesiz hesapta tutan biri için en doğru değerlendirme hangisidir?', 'Paraya kolay erişse de satın alma gücü hızla erir', ['Hiçbir risk almadığı için reel olarak kesinlikle kazanır', 'Vadesiz hesap enflasyona karşı tam koruma sağlar', 'Bankanın kendisine enflasyon kadar ek ödeme yapması zorunludur'], 'Vadesiz hesap faiz getirmediği için enflasyon kadar reel kayıp yaşanır; likiditenin bedeli satın alma gücü kaybıdır.'),
  ('Bankaların sermaye yeterliliği oranı temel olarak neyi gösterir?', 'Bankanın özkaynaklarının riskli varlıklarını ne ölçüde karşıladığını', ['Bankanın şubelerinde kaç kasa bulunduğunu', 'Bankanın günlük nakit çekim sınırını', 'Bankanın reklam ve tanıtım harcamalarının toplam faaliyet giderlerine oranını'], 'Sermaye yeterliliği, özkaynakların risk ağırlıklı varlıklara oranıdır; olası zararları karşılayacak sermaye tamponunu ölçer.'),
  ('Teminatlı krediler teminatsız kredilere göre neden genellikle daha düşük faizlidir?', 'Borç ödenmezse banka teminatı satarak alacağını tahsil edebildiği için', ['Teminatlı kredilerde bankanın hiç masrafı olmadığı için', 'Bankacılık yasaları teminatlı kredilere herhangi bir faiz uygulanmasını açıkça yasakladığı için', 'Teminatsız kredileri yalnızca merkez bankası verebildiği için'], 'Teminat, bankanın zarar etme olasılığını azaltır; daha düşük risk daha düşük risk primine, yani daha düşük faize yansır.'),
  ('Kredi sözleşmesinde "kefil" olan kişinin üstlendiği sorumluluk hangisidir?', 'Asıl borçlu ödemezse borcu ödemeyi', ['Krediyi kullanacak kişiyi bankaya tanıtmayı', 'Kredinin faiz oranını bankayla birlikte belirlemeyi', 'Kredinin hangi amaçla harcandığını denetlemeyi'], 'Kefil, asıl borçlunun ödememesi durumunda borcu ödemeyi taahhüt eder; bu nedenle kefil olmak ciddi bir mali yükümlülüktür.'),
  ('Fatih, 10 gün sonra alacağı maaşı beklerken acil bir ödeme için kredi kartı nakit avansı kullanmayı düşünüyor. Bu seçenek için en doğru uyarı hangisidir?', 'Nakit avansa genellikle ilk günden faiz işler ve maliyeti yüksektir', ['Nakit avans bankaların sadık müşterilerine sunduğu, faiz içermeyen bir hediye kampanyasıdır', 'Nakit avans alınca kredi notu kesinlikle yükselir', 'Nakit avans yalnızca döviz olarak çekilebilir'], 'Kredi kartı nakit avansında faiz genellikle çekim gününden işlemeye başlar; ek ücretlerle birlikte pahalı bir borçlanma yoludur.'),
  ('Balon ödemeli bir kredide borçlunun en çok dikkat etmesi gereken nokta hangisidir?', 'Vadenin sonunda ödenecek büyük toplu tutar', ['Taksitlerin her ay giderek artacak olması', 'Kredinin faiz içermemesi', 'Kredinin hiçbir koşulda erken kapatılamaması'], 'Balon ödemeli kredilerde ara taksitler düşüktür ama vade sonunda büyük bir toplu ödeme yapılır; bu tutarın hazırlanmaması temerrüde yol açabilir.'),
  ('Kredi kartında limitin büyük bölümünü sürekli dolu tutmak kredi değerlendirmesini neden olumsuz etkileyebilir?', 'Yüksek limit kullanım oranı borçlunun finansal baskı altında olduğu izlenimini verir', ['Bankalar limit kullanan herkese ceza vergisi kesmek zorundadır', 'Limit kullanım oranı belirli bir eşiği aşan kartlar banka tarafından otomatik olarak iptal edilir', 'Kredi notu yalnızca kart sayısına bakılarak hesaplanır'], 'Kredi skorlama sistemleri limit kullanım oranını önemli bir gösterge sayar; limitin sürekli dolu olması yüksek borç yükü olarak yorumlanır.'),
  ('İlk modern genel amaçlı ödeme kartlarından biri kabul edilen Diners Club kartı hangi yıl çıkarılmıştır?', '1950', ['1958', '1972', '1985'], 'Diners Club kartı 1950\'de ABD\'de restoranlarda kullanılmak üzere çıkarıldı ve modern kart sistemlerinin öncülerinden biri oldu.'),
  ('Kredi kartı borcu olan biri, kart faizinin aylık oranının ihtiyaç kredisinin aylık faizinden yüksek olduğunu öğreniyor. Rasyonel bir adım hangisidir?', 'Daha düşük faizli krediyle pahalı kart borcunu kapatmayı değerlendirmek', ['Kart borcunu ödemeyip yeni kart başvurusu yapmak', 'Asgari ödemeyi de bırakıp borcun zamanla kendiliğinden kapanmasını beklemek', 'Kart limitini artırıp harcamayı sürdürmek'], 'Pahalı borcu daha ucuz borçla değiştirmek (borç yapılandırma) toplam faiz maliyetini azaltır; tabii yeni harcama yapılmaması şartıyla.'),
  ('Türkiye\'de kullanılan bir IBAN numarası toplam kaç karakterden oluşur?', '26', ['16', '22', '34'], 'Türkiye IBAN\'ı TR ile başlar ve toplam 26 karakterdir: 2 harf ülke kodu, 2 kontrol hanesi ve 22 haneli banka/hesap bilgisi.'),
  ('Uluslararası para transferlerinde kullanılan SWIFT için hangisi doğrudur?', 'Bankalar arasında güvenli finansal mesajlaşma sağlayan bir ağdır', ['Banknotları ülkeler arasında fiziksel olarak taşıyan uluslararası bir kargo şirketidir', 'Bir ülkenin merkez bankasının kullandığı kripto paradır', 'Yalnızca hisse senedi alım satımı yapan bir borsadır'], 'SWIFT parayı doğrudan taşımaz; bankaların ödeme talimatlarını standart ve güvenli mesajlarla birbirine iletmesini sağlayan bir ağdır.'),
  ('Bir kişi telefonla aranıp "hesabınız tehlikede, kartınıza gelen tek kullanımlık şifreyi söyleyin" deniyor. En doğru davranış hangisidir?', 'Şifreyi kimseyle paylaşmayıp bankayı resmî kanaldan kendisi aramak', ['Arayan kişi banka adını ve kendi adını doğru bildiği için şifreyi hemen söylemek', 'Şifrenin yarısını söyleyip kalanını mesajla göndermek', 'Şifreyle birlikte kart numarasını ve son kullanma tarihini de ekleyerek arayan kişiye iletmek'], 'Bankalar tek kullanımlık şifreyi telefonda asla istemez; bu bir dolandırıcılık yöntemidir ve doğrulama yalnızca resmî kanallardan yapılmalıdır.'),
  ('Aşağıdaki davranışlardan hangisi kişinin kredi notunu düşürme olasılığı en yüksek olanıdır?', 'Kredi taksitlerini birkaç ay üst üste geciktirmek', ['Faturaları otomatik ödemeye bağlamak', 'Kart borcunu her ay tamamen kapatmak', 'Uzun süredir sorunsuz biçimde kullanılan eski kredi kartını iptal etmeden korumak'], 'Gecikmiş ödemeler kredi geçmişine olumsuz kayıt olarak işlenir ve notu en çok düşüren etkenlerden biridir.'),
  ('Hiç kredi kullanmamış ve kredi kartı olmayan genç bir çalışan için kredi notu açısından en doğru değerlendirme hangisidir?', 'Kredi geçmişi olmadığı için risk ölçülemeyebilir ve ilk kredide zorlanabilir', ['Hiç borcu olmadığı için mutlaka en yüksek puanı alır', 'Kredi notu yalnızca aylık maaşa göre hesaplandığı için onun puanı kesinlikle çok yüksektir', 'Bankalar kredi geçmişi olmayan kişilere yasal olarak kredi veremez'], 'Kredi notu geçmiş davranıştan beslenir; veri yoksa banka riski ölçemez. Küçük bir limiti düzenli kullanıp ödemek geçmiş oluşturmaya yardım eder.'),
  ('Mevduat sigortasının banka hücumu riskini azaltmasının nedeni hangisidir?', 'Mevduat sahipleri paralarının güvencede olduğunu bildiği için panikle para çekmez', ['Bankaların mevduat çekilmesini yasal olarak engellemesine izin verir', 'Bankaları kredi vermekten tamamen alıkoyar', 'Bankaların topladıkları bütün mevduatı her zaman nakit olarak kendi kasalarında tutmasını zorunlu kılar'], 'Banka hücumu, herkesin parasını kaybetme korkusuyla aynı anda çekmeye çalışmasıdır; güvence bu korkuyu ortadan kaldırarak panik zincirini kırar.'),
  ('Bankacılıkta "ahlaki tehlike" kavramına uygun örnek hangisidir?', 'Kurtarılacağını düşünen bir bankanın aşırı riskli krediler vermesi', ['Bankanın müşterilerine ücretsiz takvim dağıtması', 'Bankanın şube açılışında tören düzenlemesi', 'Bankanın internet sitesini ve mobil uygulamasını kullanıcı isteğiyle yenilemesi'], 'Ahlaki tehlike, zararın başkasınca karşılanacağını bilen tarafın daha fazla risk almasıdır; güvence sistemlerinin olası yan etkisidir.'),
  ('Sağlam bir bankada bile "banka batıyor" söylentisi yayılması bankayı neden zor durumda bırakabilir?', 'Bankalar mevduatın yalnızca küçük bir bölümünü nakit tuttuğu için herkes aynı anda çekemez', ['Söylentiler bankanın kredilerini kendiliğinden siler', 'Hakkında söylenti çıkan bankanın uyguladığı bütün faiz oranları yasa gereği hemen sıfırlanır', 'Bankanın merkez bankasıyla bağı otomatik olarak kesilir'], 'Kısmi rezerv sisteminde mevduatın çoğu krediye dönüşmüştür; panikle gelen toplu çekim talepleri kasadaki nakdi aşar ve sağlam banka da likidite krizine girebilir.'),
  ('Üretici fiyat endeksi (ÜFE) tüketici fiyat endeksinden (TÜFE) temel olarak neyle ayrılır?', 'Üreticilerin sattığı malların fiyatlarını üretici aşamasında ölçmesiyle', ['Yalnızca ithal edilen ürünlerin mağazalardaki perakende satış fiyatlarını izlemesiyle', 'Hizmet fiyatlarını tüketicilerin ödediği biçimiyle ölçmesiyle', 'Yalnızca ev kiralarındaki değişimi ölçmesiyle'], 'ÜFE, üreticilerin mallarını sattığı fiyatların değişimini ölçer; TÜFE ise son tüketicinin ödediği fiyatları izler.'),
  ('Gıda ve enerji gibi oynak kalemlerin çıkarıldığı enflasyon göstergesi para politikasında neden izlenir?', 'Fiyatlardaki geçici şoklardan arınmış ana eğilimi görmek için', ['Manşet enflasyonu her zaman daha yüksek göstermek için', 'Yalnızca lüks ürün fiyatlarını izlemek için', 'Hanehalkının gıda ve enerji harcamalarını resmî hesaplarda tamamen sıfır göstermek için'], 'Çekirdek enflasyon, hava koşulları ya da petrol fiyatı gibi geçici şokları dışlayarak fiyatlardaki kalıcı eğilimi daha net gösterir.'),
  ('Bir öğrenci, kendi harcamalarının çoğunu kira ve yurt ücretine yaptığı için kişisel enflasyonunun resmî TÜFE\'den yüksek olduğunu düşünüyor. Bu düşünce için en doğru değerlendirme hangisidir?', 'Mümkündür; sepeti ortalama haneden farklı olan kişinin yaşadığı enflasyon da farklı olabilir', ['İmkânsızdır; ülkede yaşayan herkesin karşılaştığı enflasyon resmî oranla her zaman birebir aynıdır', 'Yalnızca resmî oranın altında kalabilir, üstüne çıkamaz', 'Kira fiyatları hiçbir zaman enflasyon hesaplamasında yer almaz'], 'Resmî endeks ortalama bir hanenin sepetine dayanır; harcama dağılımı farklı olan bireyin karşılaştığı fiyat artışı farklılaşabilir.'),
  ('Bir yıl içinde fiyat endeksi her ay yüzde 2 artarsa yıllık enflasyon için doğru olan hangisidir?', 'Yüzde 24\'ün üzerinde olur', ['Tam olarak yüzde 24 olur', 'Yüzde 24\'ten belirgin biçimde düşük olur', 'Yüzde 2 olarak kalır'], 'Aylık artışlar birbirinin üzerine eklenir: 1,02^12 ≈ 1,268; yani yıllık enflasyon yaklaşık yüzde 26,8 olur, bu da yüzde 24\'ün üzerindedir.'),
  ('Bir ürünün fiyatı ilk yıl yüzde 50, ikinci yıl yüzde 20 artıyor. İki yılda toplam fiyat artışı yüzde kaçtır?', '80', ['70', '62,5', '75'], '1,50 · 1,20 = 1,80; toplam artış yüzde 80\'dir. Oranlar toplanmaz, çarpılarak birleştirilir.'),
  ('Ücretlerin fiyatlara, fiyatların da tekrar ücretlere yansıdığı kısır döngüye ne ad verilir?', 'Ücret-fiyat sarmalı', ['Likidite tuzağı', 'Kalabalıklaştırma etkisi', 'Parasal genişleme'], 'İşçiler fiyat artışını telafi etmek için ücret artışı ister, firmalar artan maliyeti fiyatlara yansıtır; süreç kendini besleyen bir sarmala dönüşür.'),
  ('Hanehalkı ve firmalar gelecek yıl yüksek enflasyon bekliyorsa bu beklentinin bugünkü fiyatlara etkisi için en doğru yorum hangisidir?', 'Beklenti, fiyatlama ve ücret kararlarına yansıyarak kendini gerçekleştirebilir', ['Beklentiler yalnızca anketleri etkiler, gerçek fiyatlar üzerinde hiçbir etkisi yoktur', 'Yüksek enflasyon beklentisi her zaman fiyatları düşürür', 'Beklentiler yalnızca dış ticareti etkiler, iç fiyatlar ise değişmeden kalır'], 'Firmalar fiyatlarını, işçiler ücret taleplerini beklentiye göre ayarlar; bu yüzden merkez bankaları beklentileri sabitlemeye büyük önem verir.'),
  ('Talep enflasyonuyla mücadelede merkez bankasının kullanabileceği en doğrudan araç hangisidir?', 'Faizleri artırarak harcama ve kredi talebini yavaşlatmak', ['Bankalara faizsiz ve sınırsız kredi vererek toplam talebi daha da artırmak', 'Para arzını hızla genişletmek ve faizi indirmek', 'Zorunlu karşılık oranını sıfıra indirmek'], 'Faiz artışı borçlanmayı ve harcamayı pahalılaştırır; aşırı talep soğuyunca fiyat baskısı azalır.'),
  ('Deflasyon döneminde tüketicilerin satın almayı ertelemesi ekonomiye neden zarar verebilir?', 'Talep düşer, firmaların geliri azalır ve üretimle istihdam gerileyebilir', ['Fiyatların düşmesi bütün firmaları daha kârlı kılar', 'Ertelenen talep hemen ertesi gün iki katına çıkarak ekonomiyi aşırı ısıtır ve fiyatları yükseltir', 'Deflasyon borçların reel değerini kesinlikle azaltır'], 'Fiyatların düşeceğini bekleyen tüketici harcamayı erteler; talep azalınca firmalar üretimi ve istihdamı keser, bu da fiyatları daha da düşürebilir.'),
  ('Deflasyon borçlular için neden ek bir yük oluşturur?', 'Borcun nominal tutarı aynı kalırken gelirler ve fiyatlar düştüğü için reel borç yükü artar', ['Deflasyon döneminde yürürlükteki bütün borç sözleşmelerinin tutarı yasal olarak hemen ikiye katlanır', 'Deflasyon borçların faizini kendiliğinden sıfıra indirir', 'Deflasyonda bankalar borçları erken ödemeye zorlar'], 'Fisher\'in borç-deflasyon tezine göre fiyatlar düşünce aynı nominal borcu ödemek daha fazla reel gelir gerektirir.'),
  ('Hiperenflasyon yaşayan bir ülkede insanların ödemelerde yabancı para kullanmaya başlamasına ne denir?', 'Dolarizasyon', ['Gresham etkisi altında altın standardına dönüş', 'Deflasyonist sarmal', 'Kaydi paranın genişlemesi'], 'Ulusal paraya güven kaybolduğunda halk istikrarlı bir yabancı parayı değişim aracı ve değer saklama aracı olarak kullanmaya başlar; buna dolarizasyon denir.'),
  ('Beklenmeyen yüksek bir enflasyon sabit faizli borç sözleşmelerinde kimin lehine olur?', 'Borçlunun', ['Borç verenin', 'İkisinin de eşit ölçüde', 'Yalnızca bankanın'], 'Borçlu, değeri erimiş parayla geri ödeme yapar; borcun reel değeri azaldığı için beklenmeyen enflasyon borçluyu kazandırır, borç vereni kaybettirir.'),
  ('Sık fiyat değişikliği yapmak zorunda kalan bir restoranın menülerini sürekli yeniden bastırması enflasyonun hangi maliyetine örnektir?', 'Menü maliyetleri', ['Ayakkabı eskitme maliyetleri', 'Fırsat maliyetinin sıfırlanması', 'Ölçek ekonomileri'], 'Enflasyonda fiyat etiketlerini, katalogları ve menüleri güncellemenin yarattığı giderlere menü maliyeti denir.'),
  ('Yüksek enflasyonda insanların elde az nakit tutmak için bankaya daha sık gidip gelmesinin yarattığı kayba ne ad verilir?', 'Ayakkabı eskitme maliyeti', ['Menü maliyeti', 'Batık maliyet', 'Sabit üretim maliyetinin artışı'], 'Nakit tutmanın maliyeti arttıkça insanlar parayı faizli hesapta tutup sık sık çeker; bu zaman ve emek kaybına benzetmeyle ayakkabı eskitme maliyeti denir.'),
  ('Ayşe 1 yıl önce bir arkadaşına 10.000 lira borç verdi ve faiz istemedi. Bu sürede enflasyon yüzde 30 oldu. Geri aldığı paranın reel değeri yaklaşık olarak bir yıl önceki kaç liraya denk gelir?', '7.692', ['7.000', '13.000', '10.000'], 'Reel değer = 10.000 / 1,30 ≈ 7.692 liradır; Ayşe satın alma gücü olarak yaklaşık 2.300 lira kaybetmiştir.'),
  ('Enflasyon hedeflemesi rejiminde merkez bankası ne yapar?', 'Belirli bir enflasyon hedefini kamuoyuna duyurur ve politikasını bu hedefe göre yönetir', ['Döviz kurunu belirli bir düzeye sabitleyip enflasyon dahil başka hiçbir göstergeye hiç bakmaz', 'Para arzını her yıl kesinlikle aynı tutarda artırır', 'Enflasyon verilerinin yayımlanmasını yasaklar'], 'Bu rejimde sayısal hedef açıklanır, kararlar bu hedefe ulaşmak için alınır ve hesap verebilirlik için iletişim güçlendirilir.'),
  ('Birçok gelişmiş ülke merkez bankası sıfır yerine yüzde 2 civarında bir enflasyon hedefler. Bunun gerekçelerinden biri hangisidir?', 'Deflasyon riskine karşı tampon oluşturmak', ['Ücretlerin her yıl mutlaka yarıya inmesini sağlamak', 'Faizlerin sürekli negatif kalmasını garanti etmek', 'Para birimini her yıl kasıtlı olarak değersizleştirmek'], 'Hafif pozitif enflasyon deflasyona düşme riskini azaltır ve merkez bankasına faiz indirimi için alan bırakır; ölçüm sapmaları da sıfırı yanıltıcı kılabilir.'),
  ('Nominal faiz, reel faiz ve beklenen enflasyon arasındaki ilişkiyi gösteren eşitlik hangi iktisatçının adıyla anılır?', 'Irving Fisher', ['Alfred Marshall', 'Léon Walras', 'Vilfredo Pareto'], 'Fisher eşitliği ABD\'li iktisatçı Irving Fisher\'ın adını taşır: (1 + nominal) = (1 + reel) · (1 + enflasyon).'),
  ('2015\'te 20 lira olan bir sinema biletinin fiyatı 2020\'de 40 liradır. Bu dönemde fiyat endeksi 100\'den 160\'a çıkmıştır. Biletin 2015 fiyatlarıyla reel fiyatı kaç liradır?', '25', ['32', '40', '22,5'], 'Reel fiyat = 40 · (100 / 160) = 25 lira. Bilet, genel fiyatlardan daha hızlı pahalanmıştır.'),
  ('5.000 liralık bir yatırım 2 yılda basit faizle 1.200 lira faiz getirmiştir. Yıllık faiz oranı yüzde kaçtır?', '12', ['24', '6', '10,5'], 'Oran = faiz / (anapara · süre) = 1.200 / (5.000 · 2) = 0,12; yani yüzde 12.'),
  ('5.000 lira yıllık yüzde 10 ile 2 yıl değerlendiriliyor. Bileşik faiz getirisi basit faiz getirisinden kaç lira fazladır?', '50', ['100', '500', '5'], 'Basit faiz: 5.000 · 0,10 · 2 = 1.000; bileşik: 5.000 · (1,21 − 1) = 1.050. Fark 50 liradır; bu, ilk yılın faizinin kazandığı faizdir.'),
  ('Aynı nominal yıllık faiz oranında, faizin bileşik işletilme sıklığı artırılırsa (yıllıktan aylığa, aylıktan günlüğe) efektif getiri nasıl değişir?', 'Artar, ancak artış giderek küçülür ve bir sınıra yaklaşır', ['Azalır ve sonunda sıfıra iner', 'Hiç değişmez, çünkü nominal oran aynıdır', 'Bileşik işletme sıklığıyla orantılı ve sınırsız biçimde büyüyerek sonsuza gider'], 'Sıklık arttıkça efektif oran yükselir; ancak sınırda sürekli bileşik faize (e üzeri oran) yakınsar, sonsuza gitmez.'),
  ('İki arkadaştan Can 20 yaşında, Ece 30 yaşında aynı aylık tutarla, aynı getiriyle birikim yapmaya başlıyor. 60 yaşında kimin birikiminin daha büyük olması beklenir ve neden?', 'Can\'ın; bileşik getiri daha uzun süre çalıştığı için', ['Ece\'nin; geç başlayanın getirisi her zaman daha yüksektir', 'İkisinin; başlangıç yaşı birikimi hiç etkilemez', 'Ece\'nin; çünkü daha kısa sürede daha az risk alır'], 'Bileşik büyümede süre en güçlü etkendir; Can hem daha çok katkı yapar hem de ilk katkıları on yıl daha uzun süre faiz kazanır.'),
  ('Yıllık yüzde 20 bileşik faizle iki yıl sonra elde edilecek 14.400 liranın bugünkü değeri kaç liradır?', '10.000', ['12.000', '8.640', '11.520'], 'Bugünkü değer = 14.400 / 1,2² = 14.400 / 1,44 = 10.000 lira.'),
  ('Faiz oranı yüzde 15\'tir. Size bugün 9.000 lira ya da bir yıl sonra 10.000 lira teklif ediliyor. Hangi seçim daha avantajlıdır?', 'Bugün 9.000 lira almak', ['Bir yıl sonra 10.000 lira almak', 'İkisi tam olarak eşdeğerdir', 'Hesap için yeterli bilgi yoktur'], 'Bir yıl sonraki 10.000 liranın bugünkü değeri 10.000 / 1,15 ≈ 8.696 liradır; bu, 9.000 liradan azdır. Bugün 9.000\'i alıp yatırmak daha iyidir.'),
  ('İskonto oranı yükseldiğinde gelecekte alınacak sabit bir tutarın bugünkü değeri nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar, sonra kesinlikle iki katına çıkar'], 'Bugünkü değer = gelecekteki değer / (1 + r)^t; payda büyüdükçe bugünkü değer küçülür.'),
  ('Süresiz olarak her yıl 500 lira ödeyen bir varlığın, faiz oranı yüzde 5 iken bugünkü değeri kaç liradır?', '10.000', ['2.500', '25.000', '5.250'], 'Süresiz ödemenin (perpetüite) bugünkü değeri = yıllık ödeme / faiz = 500 / 0,05 = 10.000 lira.'),
  ('Yıllık yüzde 6 bileşik getiriyle büyüyen bir birikim 72 kuralına göre yaklaşık kaç yılda dört katına çıkar?', '24', ['12', '18', '36'], '72 / 6 = 12 yılda iki katına çıkar; dört katı için iki kez ikiye katlanma gerekir: 2 · 12 = 24 yıl.'),
  ('Yıllık enflasyon yüzde 24 olan bir ülkede 72 kuralına göre fiyatlar yaklaşık kaç yılda ikiye katlanır?', '3', ['24', '6', '1,5'], '72 kuralı enflasyona da uygulanabilir: 72 / 24 = 3 yıl. Bu sürede paranın satın alma gücü yaklaşık yarıya iner.'),
  ('72 kuralı hangi tür büyüme için geliştirilmiş pratik bir yaklaşımdır?', 'Bileşik büyüme', ['Basit faizli büyüme', 'Doğrusal azalma', 'Sabit tutarlı artış'], '72 kuralı, ikiye katlanma süresinin ln 2 / ln(1 + r) olduğu bileşik büyüme için kullanılan bir kestirmedir; düşük ve orta oranlarda iyi sonuç verir.'),
  ('Piyasa faizlerinin hızla yükseldiği bir dönemde hangi borçlu en çok zorlanır?', 'Değişken faizli konut kredisi olan borçlu', ['Sabit faizli taşıt kredisi olan borçlu', 'Hiç borcu bulunmayan tasarruf sahibi', 'Borcunu geçen yıl tamamen kapatmış ve yeni kredi kullanmayan kişi'], 'Değişken faizli kredide oran referans faize göre güncellenir; faizler yükselince taksitler de artar.'),
  ('Değişken faizli kredilerde faizin hangi göstergeye bağlanarak güncellendiğini ifade eden kavram hangisidir?', 'Referans (gösterge) faiz oranı', ['Yıllık maliyet oranı', 'Gecikme faizi', 'Temerrüt faizi'], 'Değişken faiz, belirli bir referans orana (örneğin bankalararası bir gösterge faize) bir sabit marj eklenerek belirlenir.'),
  ('Aynı vadede bir şirketin tahvili devlet tahvilinden daha yüksek faiz veriyorsa aradaki farkın temel nedeni hangisidir?', 'Şirketin borcunu ödememe riski için istenen risk primi', ['Şirket tahvillerinin hiç vergilendirilmemesi', 'Devlet tahvillerinin her zaman daha uzun vadeli olması', 'Şirketlerin yasa gereği daha fazla faiz ödemek zorunda olması'], 'Yatırımcılar temerrüt riski taşıyan borçluya borç verirken ek bir getiri, yani kredi risk primi ister.'),
  ('Getiri eğrisi neyi gösterir?', 'Aynı kalitedeki borçlanma araçlarının vadeye göre faiz oranlarını', ['Bir hisse senedinin günlük fiyat hareketini', 'Enflasyonun aylara göre dağılımını', 'Bankaların hissedarlarına yaptıkları kâr payı dağıtımının yıllık takvimini'], 'Getiri eğrisi, benzer kredi riskindeki tahvillerin (genellikle devlet tahvillerinin) faizlerini kısa vadeden uzun vadeye doğru gösterir.'),
  ('Kısa vadeli faizlerin uzun vadeli faizlerin üzerine çıktığı ters getiri eğrisi çoğu zaman neyin habercisi olarak yorumlanır?', 'Ekonomik yavaşlama ya da durgunluk beklentisinin', ['Enflasyonun kesinlikle artacağının', 'Konut fiyatlarının mutlaka ikiye katlanacağının', 'Bankaların tamamen faizsiz çalışmaya başlayacağının'], 'Ters eğri piyasanın gelecekte faiz indirimleri beklediğini gösterir; bu beklenti çoğunlukla yavaşlama ya da resesyon öngörüsüyle ilişkilidir.'),
  ('Gelecek dönemde enflasyonun artacağı beklentisi yaygınlaşırsa yeni verilecek kredilerin nominal faiz oranı nasıl etkilenir?', 'Yükselme eğilimine girer', ['Kesinlikle sıfıra iner', 'Beklentilerden hiç etkilenmez', 'Yalnızca mevduat faizleri değişir'], 'Borç verenler reel getirilerini korumak için beklenen enflasyonu faize ekler; Fisher etkisi gereği nominal faizler yükselir.'),
  ('Yıllık 100 lira kupon ödeyen bir tahvil piyasada 800 liradan satılıyorsa cari getirisi yüzde kaçtır?', '12,5', ['10', '8', '11,25'], 'Cari getiri = yıllık kupon / piyasa fiyatı = 100 / 800 = 0,125; yani yüzde 12,5.'),
  ('Faiz ödemesi yapmayan, nominal değerinin altında satılan ve getirisi aradaki farktan oluşan borçlanma aracına ne ad verilir?', 'İskontolu (kuponsuz) tahvil', ['Değişken kuponlu tahvil', 'Hisse senedine dönüştürülebilir tahvil', 'Süresiz ve kupon ödemeli tahvil'], 'Kuponsuz tahvil vadede nominal değeri öder; bugün daha düşük fiyattan alınır ve getiri bu fiyat farkıdır.'),
  ('Bir şirket iflas ettiğinde tasfiyeden kalan paradan öncelikle hangi grubun alacağı karşılanır?', 'Şirketin tahvillerini elinde tutan alacaklıların', ['Şirketin adi hisse senedi sahiplerinin', 'Şirketin yönetim kurulu üyelerinin hisse paylarının', 'Şirketin hisse almak için başvuru yapmış yatırımcıların'], 'Tahvil sahipleri alacaklıdır ve ortaklardan (hissedarlardan) önce gelir; hissedarlar ancak borçlar ödendikten sonra kalan varsa pay alır.'),
  ('Kredi derecelendirme kuruluşlarının not skalasında genellikle en yüksek kredi kalitesini gösteren not hangisidir?', 'AAA', ['BBB', 'CCC', 'D'], 'AAA en düşük temerrüt riskini gösterir; D ise temerrüde düşmüş borçluyu ifade eder.'),
  ('Yüksek getirili ama düşük kredi notlu (spekülatif dereceli) tahviller için en doğru değerlendirme hangisidir?', 'Yüksek getiri, yüksek temerrüt riskinin bedeli olarak sunulur', ['Bu tahviller devlet güvencesinde olduğu için risksizdir', 'Yüksek getiri kesinlikle anaparanın korunacağını gösterir', 'Kredi notu düşük olan tahviller yasa gereği hiçbir koşulda faiz ödemez ve anaparası güvencededir'], 'Borçlunun ödeyememe olasılığı arttıkça yatırımcı daha yüksek getiri ister; bu tahvillerde anapara kaybı riski belirgindir.'),
  ('Borsa İstanbul\'un öncülü olan İstanbul Menkul Kıymetler Borsası hangi yıl faaliyete başlamıştır?', '1986', ['1923', '1974', '2005'], 'İMKB 1985\'te kuruldu, 1986\'da işlemlere başladı; 2013\'te Borsa İstanbul adını aldı.'),
  ('Bir şirketin 200 milyon adet hissesi vardır ve hisse fiyatı 15 liradır. Şirketin piyasa değeri kaç milyar liradır?', '3', ['30', '0,3', '13,3'], 'Piyasa değeri = hisse sayısı · fiyat = 200 milyon · 15 = 3.000 milyon = 3 milyar lira.'),
  ('Bir yatırımcının sahip olmadığı hisseyi ödünç alıp satması ve fiyat düşünce daha ucuza geri alıp iade etmesine ne ad verilir?', 'Açığa satış', ['Halka arz', 'Bedelli sermaye artırımı', 'Uzun pozisyon açma'], 'Açığa satışta yatırımcı fiyat düşüşünden kazanç bekler; fiyat yükselirse zarar teorik olarak sınırsızdır.'),
  ('Bedelsiz sermaye artırımıyla bir şirketin hisse sayısı iki katına çıkarsa diğer koşullar sabitken ne olması beklenir?', 'Hisse fiyatı yaklaşık yarıya iner, toplam piyasa değeri değişmez', ['Hisse fiyatı aynı kalır ve şirketin piyasa değeri iki katına çıkar', 'Şirketin kasasına yeni nakit sermaye girer', 'Hissedarların şirketteki ortaklık oranı yarıya düşer'], 'Bedelsiz artırımda şirkete yeni para girmez; mevcut değer daha çok hisseye bölünür. Teorik fiyat düşer, ortakların payı ve toplam değer korunur.'),
  ('Borsa yatırım fonlarını (BYF) klasik yatırım fonlarından ayıran özellik hangisidir?', 'Gün içinde borsada hisse senedi gibi alınıp satılabilmeleri', ['Hiçbir varlığa yatırım yapmamaları', 'Yalnızca bankalar tarafından alınabilmeleri', 'Getirilerinin devlet tarafından her koşulda yasal olarak garanti edilmesi'], 'BYF\'ler borsada işlem gördüğü için gün içinde anlık fiyatla alınıp satılabilir; klasik fonlarda ise işlem günlük fiyat üzerinden gerçekleşir.'),
  ('Aktif yönetilen fonlarla pasif endeks fonları karşılaştırıldığında genellikle hangisi doğrudur?', 'Pasif fonların yönetim ücretleri daha düşüktür', ['Aktif fonlar her yıl ve her piyasa koşulunda endeksi kesinlikle geçer', 'Pasif fonların hiçbir piyasa riski yoktur', 'Aktif fonlarda yönetim ücreti hiç alınmaz'], 'Pasif fonlar analiz ve sık alım satım gerektirmediğinden daha ucuzdur; aktif fonların uzun vadede endeksi geçmesi ise garanti değildir.'),
  ('Bir yatırım fonunun birim pay değerinin hesaplanmasında kullanılan büyüklük hangisidir?', 'Fonun toplam net varlık değerinin dolaşımdaki pay sayısına bölünmesi', ['Fon yöneticisinin aylık maaşı', 'Fonun reklam bütçesinin büyüklüğü', 'Fonun kuruluş yılında belirlenen ve hiç değişmeyen ilk pay fiyatının yeniden kullanılması'], 'Fon payının fiyatı, fon portföyünün net varlık değerinin toplam pay sayısına bölünmesiyle bulunur.'),
  ('Çeşitlendirme hangi tür riski azaltamaz?', 'Bütün piyasayı etkileyen sistematik riski', ['Tek bir şirketin iflas etme riskini', 'Tek bir sektöre özgü düzenleme riskini', 'Bir şirketin yöneticisinin hata yapma riskini'], 'Şirkete ya da sektöre özgü riskler çeşitlendirmeyle azaltılabilir; faiz, resesyon ya da savaş gibi bütün piyasayı etkileyen sistematik risk ise azaltılamaz.'),
  ('Çeşitlendirmenin en etkili olduğu portföy hangisidir?', 'Getirileri birbirleriyle düşük ya da negatif ilişkili varlıklardan oluşan portföy', ['Aynı sektördeki beş şirketin hisselerinden oluşan portföy', 'Getirileri hep aynı yönde ve aynı oranda hareket eden çok sayıda varlıktan oluşan portföy', 'Tek bir hisse senedine yoğunlaşmış portföy'], 'Bir varlık değer kaybederken diğeri kazanıyorsa ya da bağımsız hareket ediyorsa toplam dalgalanma azalır; düşük korelasyon çeşitlendirmenin anahtarıdır.'),
  ('Bir portföyün yüzde 60\'ı yüzde 20 getiri sağlayan hisselerde, yüzde 40\'ı yüzde 10 getiri sağlayan tahvillerdedir. Portföyün getirisi yüzde kaçtır?', '16', ['15', '30', '14,5'], 'Ağırlıklı ortalama: 0,60 · 20 + 0,40 · 10 = 12 + 4 = yüzde 16.'),
  ('Bir yatırım yüzde 50 değer kaybettikten sonra başlangıç değerine dönebilmesi için yüzde kaç değer kazanması gerekir?', '100', ['50', '75', '25'], '100 liralık yatırım 50 liraya düşer; tekrar 100\'e çıkması için 50 lira, yani 50 liranın yüzde 100\'ü kadar artması gerekir.'),
  ('Bir hisse senedinin betası 1,5 ise piyasa yüzde 10 yükseldiğinde bu hissenin ortalama olarak ne kadar hareket etmesi beklenir?', 'Yüzde 15 yükselmesi', ['Yüzde 10 düşmesi', 'Yüzde 1,5 yükselmesi', 'Hiç hareket etmemesi'], 'Beta, hissenin piyasaya duyarlılığıdır; 1,5 beta piyasa hareketinin ortalama 1,5 katı tepki anlamına gelir: 1,5 · 10 = yüzde 15.'),
  ('Üç yıl sonra ev peşinatı için kullanacağı birikimi olan biri için en uygun yaklaşım hangisidir?', 'Parayı görece düşük riskli ve likit araçlarda tutmak', ['Bütün birikimi tek bir küçük şirketin hissesine yatırmak', 'Birikimi yüksek kaldıraçlı işlemlerle büyütmeye çalışmak', 'Parayı kısa vadeli kripto spekülasyonunda değerlendirmek'], 'Kısa yatırım ufkunda değer kaybını telafi edecek zaman yoktur; bu yüzden hedefe yakın paralar oynaklığı düşük ve kolay nakde dönen araçlarda tutulmalıdır.'),
  ('Bir yatırım danışmanı "risksiz yüzde 10 aylık getiri garantisi" sunuyor. Bu teklif için en doğru değerlendirme hangisidir?', 'Risk-getiri ilkesine aykırıdır ve dolandırıcılık işareti olabilir', ['Garanti verildiği için kesinlikle güvenilirdir', 'Aylık getiriler yıllık getirilerle aynı anlama geldiği için bu oran piyasada olağandır', 'Yüksek getiri her zaman düşük risk anlamına gelir'], 'Piyasadaki risksiz getirinin çok üzerinde bir oranı risksiz diye sunmak gerçekçi değildir; aylık yüzde 10 bileşik olarak yılda üç katı aşan bir getiri demektir.'),
  ('Bütün birikimini iki dairelik bir gayrimenkule yatıran ama hiç nakdi olmayan bir aile ani bir sağlık harcamasıyla karşılaşıyor. Ailenin yaşadığı sorun en iyi hangi kavramla açıklanır?', 'Likidite sıkıntısı', ['Aşırı çeşitlendirme', 'Negatif enflasyon', 'Bileşik faiz kaybı'], 'Aile varlık zengini olsa da bu varlıklar hızla nakde dönmediği için kısa vadeli ödemeleri karşılayamaz; bu, likidite sıkıntısıdır.'),
  ('Bir menkul kıymetin alış ve satış fiyatları arasındaki farkın çok geniş olması neye işaret eder?', 'Piyasanın sığ ve likiditesinin düşük olduğuna', ['Varlığın kesinlikle değer kazanacağına', 'Varlığın faiz getirisinin sıfır olduğuna', 'Piyasada çok sayıda alıcı ve satıcı bulunduğuna'], 'Az sayıda alıcı ve satıcının olduğu piyasalarda alış-satış makası açılır; bu, işlem yapmanın maliyetli ve likiditenin düşük olduğunu gösterir.'),
  ('Likiditesi düşük bir yatırımın likit bir yatırıma göre genellikle daha yüksek getiri sunmasının nedeni hangisidir?', 'Yatırımcılar paralarını kolay çıkaramamanın bedeli olarak likidite primi ister', ['Likit olmayan yatırımlar devlet güvencesindedir', 'Likit varlıkların getirisi her ülkede yasayla belirli bir oranın altında tutulmak zorundadır', 'Düşük likidite hiçbir risk taşımaz'], 'Parayı gerektiğinde hızla çekememek bir risktir; bu dezavantajı üstlenen yatırımcı ek getiri olarak likidite primi bekler.'),
  ('Bir yatırımcı 10.000 lira kendi parası ve 40.000 lira borçla 50.000 liralık hisse alıyor. Hisse yüzde 10 değer kazanırsa (faiz ve masraf ihmal edilirse) kendi parasına göre getirisi yüzde kaçtır?', '50', ['10', '40', '12,5'], 'Pozisyon 5.000 lira kazanır; bu kazanç 10.000 liralık özkaynağın yüzde 50\'sidir. Kaldıraç 5 kat olduğu için getiri de 5 katına çıkar.'),
  ('10 kat kaldıraçla işlem yapan bir yatırımcının pozisyonu yüzde 10 değer kaybederse kendi sermayesine ne olur (faiz ve masraf ihmal)?', 'Tamamen kaybolur', ['Yüzde 10 azalır', 'Yüzde 1 azalır', 'Sermayesi iki katına çıkar'], '10 kat kaldıraçta yüzde 10\'luk kayıp, pozisyonun sermayeye eşit kısmını siler; yatırımcının bütün özkaynağı yok olur.'),
  ('Kredili işlemlerde teminat değeri belirli bir eşiğin altına düştüğünde aracı kurumun yatırımcıdan ek teminat istemesine ne ad verilir?', 'Teminat tamamlama çağrısı', ['Halka arz talep toplama', 'Temettü dağıtım bildirimi', 'Bedelsiz sermaye artırımı duyurusu ve hak kullanımı'], 'Kaldıraçlı pozisyon zarar edince teminat yetersiz kalır; aracı kurum ek teminat ister, yatırımcı veremezse pozisyon kapatılabilir.'),
  ('Kaldıraçlı döviz ya da kripto işlemleri yeni başlayan küçük yatırımcılar için neden özellikle riskli sayılır?', 'Küçük fiyat dalgalanmaları bile kısa sürede sermayenin tamamını silebilir', ['Kaldıraç kullanan yatırımcı yasal olarak zarar edemez', 'Kaldıraç her işlemde kazancı garanti altına alır', 'Kaldıraçlı işlemler yalnızca devlet tahvili ile yapılabildiği için hiçbir fiyat dalgalanması yaşanmaz'], 'Kaldıraç kayıpları büyütür; deneyimsiz yatırımcılar kısa sürede teminat çağrısı ve zorunlu pozisyon kapatmayla bütün paralarını kaybedebilir.'),
  ('Değerli metallerin fiyatlandırmasında kullanılan bir troy ons yaklaşık kaç gramdır?', '31,1', ['28,35', '24,0', '35,5'], 'Bir troy ons 31,1035 gramdır; günlük ons (28,35 g) ile karıştırılmamalıdır.'),
  ('Altının kriz dönemlerinde "güvenli liman" olarak görülmesinin temel nedeni hangisidir?', 'Herhangi bir kurumun borcu olmaması ve değerinin yüzyıllardır kabul görmesi', ['Altının her yıl sabit faiz ödemesi', 'Altın fiyatının hiçbir zaman düşmemesi', 'Altının bugün dünyadaki bütün ülkelerde resmî ve tek geçerli para birimi olarak kullanılması'], 'Altın bir şirketin ya da devletin ödeme vaadine dayanmaz; bu yüzden finansal sistemin sarsıldığı dönemlerde talep görür. Yine de fiyatı dalgalanabilir.'),
  ('Altın yatırımına yöneltilen temel eleştirilerden biri hangisidir?', 'Faiz ya da temettü gibi düzenli bir nakit getirisi sağlamaması', ['Fiyatının yalnızca yasa ile belirlenmesi', 'Hiçbir koşulda nakde çevrilememesi', 'Kriz dönemlerinde değerinin kesinlikle ve kalıcı olarak sıfırlanması nedeniyle hiç alıcı bulamaması'], 'Altın tutmak kendi başına nakit akışı üretmez; getirisi yalnızca fiyat artışından gelir. Saklama maliyeti de olabilir.'),
  ('Bütçesini incelediğinde her gün aldığı kahveye ayda 3.000 lira harcadığını fark eden bir öğrenci bu harcamayı kesip parayı biriktirirse bir yılda faizsiz olarak kaç lira biriktirir?', '36.000', ['3.000', '30.000', '12.000'], '3.000 · 12 = 36.000 lira. Küçük ama düzenli harcamalar yıllık toplamda önemli tutarlara ulaşır.'),
  ('"Önce kendine öde" ilkesi bütçe yönetiminde hangi uygulamayı önerir?', 'Maaş gelir gelmez birikim payını ayırıp kalanı harcamak', ['Önce bütün isteklere harcayıp kalan varsa biriktirmek', 'Gelirin tamamını önce eğlenceye ayırmak', 'Faturaları ödemeden önce kredi kartı limitini tamamen doldurup asgari ödemeyle yetinmek'], 'Ay sonunda kalanı biriktirmek yerine birikimi ilk gider kalemi gibi görmek tasarrufu düzenli hâle getirir; otomatik talimat bu ilkeyi kolaylaştırır.'),
  ('Aylık geliri 40.000 lira olan Deniz\'in aylık borç taksitleri toplamı 2.000 liradır. Borç taksitlerinin gelire oranı yüzde kaçtır?', '5', ['20', '2', '50'], '2.000 / 40.000 = 0,05; yani yüzde 5. Bu oran borç yükünün gelire göre ne kadar ağır olduğunu gösterir.'),
  ('Değişken giderlerin bütçede ayrıca izlenmesinin temel faydası hangisidir?', 'Kısılabilecek harcamaları belirlemeyi kolaylaştırması', ['Kira ve aidat gibi sabit ödemeleri kendiliğinden ve kalıcı olarak düşürmesi', 'Gelir vergisini otomatik olarak azaltması', 'Kredi faizlerini sıfırlaması'], 'Gıda dışı alışveriş, eğlence ve ulaşım gibi değişken giderler kişinin kontrolündedir; bunları izlemek tasarruf fırsatlarını ortaya çıkarır.'),
  ('Bütçesi her ay açık veren bir aile için en uygun ilk adım hangisidir?', 'Harcamaları kalem kalem kaydedip zorunlu olmayanları azaltmak', ['Açığı kapatmak için her ay yeni bir kredi kartı almak', 'Kira ve faturaları ödemeyi tamamen bırakmak', 'Açığı borsada yüksek kaldıraçlı işlemlerle hızlıca kapatmaya çalışmak'], 'Kalıcı açık, gelir-gider dengesinin bozulduğunu gösterir; önce harcamaları görünür kılmak ve ertelenebilir olanları kısmak gerekir. Borçla açık kapatmak sorunu büyütür.'),
  ('Acil durum fonunun hangi tür araçta tutulması en uygundur?', 'Kolayca erişilebilen ve değer kaybı riski düşük bir hesapta', ['Satışı aylar sürebilecek bir arsada', 'Değeri bir gün içinde yüzde 20 dalgalanabilen yeni çıkmış bir kripto parada', 'Vadesi 10 yıl sonra dolacak bir tahvilde'], 'Acil durumda paraya hemen ve tam değeriyle ulaşmak gerekir; bu yüzden likit ve düşük riskli araçlar tercih edilir.'),
  ('Serbest çalışan ve geliri aydan aya çok dalgalanan biri için acil durum fonu konusunda en doğru değerlendirme hangisidir?', 'Düzenli maaş alan birine göre daha büyük bir fon tutması akıllıca olur', ['Geliri dalgalı olduğu için hiç fon tutmaması gerekir', 'Fonun tamamını tek bir hissede tutmalıdır', 'Ayrı bir fon tutmak yerine birkaç kredi kartının toplam limitine güvenmesi yeterlidir'], 'Gelir belirsizliği arttıkça gelirsiz geçebilecek dönem uzayabilir; bu nedenle daha uzun süreyi karşılayacak bir yastık önerilir.'),
  ('Enflasyonun yüksek olduğu bir ortamda acil durum fonunun büyüklüğü için hangi uygulama daha doğrudur?', 'Fon hedefini artan giderlere göre düzenli aralıklarla güncellemek', ['Bir kez belirlenen nominal tutarı, fiyatlar ne kadar artarsa artsın yıllarca hiç değiştirmemek', 'Fonu nakit olarak evde tutup dokunmamak', 'Fonu harcayıp yerine borç limiti tanımlatmak'], 'Giderler fiyat artışıyla büyüdükçe aynı nominal fon daha az ayı karşılar; hedef tutarın giderlerle birlikte güncellenmesi gerekir.'),
  ('Her ay maaş yatar yatmaz birikim hesabına otomatik talimatla para aktarılmasının en önemli faydası nedir?', 'Harcama kararından önce birikimi garanti altına alarak irade zaafını aşması', ['Birikime bankanın iki kat faiz ödemesini zorunlu kılması', 'Gelir vergisini tamamen ortadan kaldırması', 'Kişinin kredi notunu her ay otomatik olarak iki katına çıkararak kredi limitini artırması'], 'Otomatik talimat birikimi alışkanlığa dönüştürür; para harcanma fırsatı doğmadan ayrıldığı için anlık isteklere yenik düşme olasılığı azalır.'),
  ('Kartopu yöntemini çığ yöntemine tercih eden birinin gerekçesi en çok hangi alanla açıklanır?', 'Davranışsal motivasyon', ['Faiz matematiği', 'Vergi hukuku', 'Kur ve dış ticaret politikası'], 'Kartopu yöntemi çoğu zaman daha fazla faiz ödetir; tercih edilmesinin nedeni borçları tek tek kapatmanın verdiği psikolojik motivasyondur.'),
  ('Bir kişinin kredi kartı borcuna aylık yüzde 4, ihtiyaç kredisine aylık yüzde 2,5 faiz işliyor. Elindeki fazladan 5.000 lirayı hangi borca yatırması toplam faizi daha çok azaltır?', 'Kart borcuna', ['Daha düşük faizli ihtiyaç kredisine', 'İkisine yarı yarıya', 'Borç ödemek yerine nakit tutmaya'], 'Ek ödeme en pahalı borca yapıldığında en fazla faiz tasarruf edilir; burada en yüksek oran kredi kartındadır.'),
  ('Borçlarını yapılandırmak isteyen birine bir firmanın "önce 10.000 lira ücret yatırın, bütün borçlarınızı sileriz" demesi için en doğru değerlendirme hangisidir?', 'Peşin ücret isteyen gerçekçi olmayan vaatler dolandırıcılık işaretidir', ['Banka borçlarını silme yetkisi her özel danışmanlık firmasında bulunduğu için teklif güvenilirdir', 'Ücret ödenince borçlar yasal olarak kendiliğinden silinir', 'Bu tür firmalar bankaların resmî temsilcisi sayılır'], 'Borçlar ancak alacaklıyla anlaşma ya da yasal süreçlerle yeniden yapılandırılabilir; peşin para alıp borç silme vaadi tipik bir dolandırıcılık kalıbıdır.'),
  ('Borç yapılandırması kavramı en doğru biçimde hangisini anlatır?', 'Borcun vade, faiz ya da taksit koşullarının yeniden düzenlenmesi', ['Borcun tamamının alacaklı tarafından bağışlanması', 'Borçlunun adının kredi kayıtlarından silinmesi', 'Borcun alacaklının onayı aranmadan başka bir ülkenin parasına çevrilmesi'], 'Yapılandırmada borç ortadan kalkmaz; ödeme gücüne uygun olması için taksit sayısı, vade ya da faiz yeniden belirlenir.'),
  ('Eşit taksitli bir kredide taksit tutarı her ay aynı kalırken taksidin içindeki faiz ve anapara payları zamanla nasıl değişir?', 'Faiz payı azalır, anapara payı artar', ['Faiz payı artar, anapara payı azalır', 'İkisi de her ay sabit kalır', 'Son taksit tamamen faizden oluşur, anapara ise ilk taksitte ödenir'], 'Faiz her ay kalan anaparaya işler; anapara azaldıkça faiz payı küçülür ve aynı taksitin daha büyük kısmı anaparayı kapatmaya gider.'),
  ('Bir kişi ödeme planını incelerken kredinin ilk yıllarında taksitlerin çoğunun faize gittiğini görüyor. Bu bilgiyle yapılabilecek en mantıklı hamle hangisidir?', 'Mümkünse erken dönemde ara ödemeyle anaparayı azaltmak', ['Taksitleri bilerek geciktirerek faizi düşürmek', 'Krediyi kapatmak için daha yüksek faizli yeni kredi çekmek', 'Ödeme planını bankaya iade edip taksitleri durdurmak'], 'Erken dönemde yapılan ara ödeme anaparayı düşürür; sonraki bütün dönemlerde faiz daha küçük bakiyeye işlediği için tasarruf büyük olur.'),
  ('Muafiyeti 5.000 lira olan bir poliçede 30.000 liralık bir hasar oluşursa sigorta şirketi (diğer koşullar uygunsa) kaç lira öder?', '25.000', ['30.000', '35.000', '55.000'], 'Muafiyet hasarın sigortalı tarafından karşılanan kısmıdır: 30.000 − 5.000 = 25.000 lira şirketçe ödenir.'),
  ('1999 depremlerinin ardından Türkiye\'de konutlar için zorunlu hâle getirilen deprem sigortasını yürüten kurum hangisidir?', 'DASK', ['TMSF', 'SGK', 'TARSİM'], 'Doğal Afet Sigortaları Kurumu (DASK) 2000 yılında kuruldu ve zorunlu deprem sigortasını yürütür.'),
  ('Sigortacılığın dayandığı "büyük sayılar yasası" hangi fikri anlatır?', 'Çok sayıda benzer risk bir araya gelince toplam hasar daha öngörülebilir olur', ['Büyük binaların sigortası her zaman daha ucuzdur', 'Sigorta şirketi büyüdükçe prim kesinlikle sıfıra iner', 'Sigortalı sayısı arttıkça her bir kişinin hasara uğrama olasılığı da aynı oranda artar'], 'Tek bir kişinin hasarı öngörülemez; ama çok sayıda benzer sigortalının ortalama hasarı istatistiksel olarak tahmin edilebilir ve prim buna göre belirlenir.'),
  ('Aynı sigorta için yüksek muafiyetli bir poliçenin primi düşük muafiyetliye göre genellikle nasıldır ve neden?', 'Daha düşüktür; küçük hasarları sigortalı kendisi üstlenir', ['Daha yüksektir; çünkü muafiyet arttıkça şirketin ödeyeceği tazminat yükü de artar', 'Aynıdır; muafiyet primi etkilemez', 'Daha yüksektir; yasa bunu zorunlu kılar'], 'Yüksek muafiyette şirket küçük hasarları ödemez ve beklenen ödemesi azalır; bu da primi düşürür.'),
  ('Genç ve sağlıklı, bakmakla yükümlü olduğu kimse olmayan bir öğrencinin yüksek teminatlı hayat sigortası yaptırması için en doğru yorum hangisidir?', 'Bakmakla yükümlü olduğu kimse olmadığından öncelikli bir ihtiyaç değildir', ['Herkes için ilk ve en zorunlu finansal adımdır', 'Hayat sigortası her koşulda piyasadaki en yüksek getirili yatırım aracıdır', 'Genç yaşta hayat sigortası yasal olarak zorunludur'], 'Hayat sigortası geride kalanların gelirini korumak içindir; bakmakla yükümlü olunan kimse yoksa öncelik acil durum fonu ve sağlık güvencesi gibi ihtiyaçlarda olur.'),
  ('Türkiye\'de Bireysel Emeklilik Sistemi (BES) hangi yıl fiilen faaliyete geçmiştir?', '2003', ['1985', '1995', '1999'], 'BES\'in yasası 2001\'de çıktı; sistem 2003\'te fiilen işlemeye başladı. 2017\'de ise çalışanlar için otomatik katılım uygulaması getirildi.'),
  ('Kamu sosyal güvenlik sistemlerinin çoğunda bugünkü çalışanların primleriyle bugünkü emeklilerin aylıklarının ödendiği yapıya ne ad verilir?', 'Dağıtım (kuşaklar arası) sistemi', ['Bireysel hesaplarda fon biriktirme sistemi', 'Kaldıraçlı yatırım sistemi', 'Altın standardı sistemi'], 'Dağıtım sisteminde toplanan primler doğrudan mevcut emeklilere dağıtılır; bu yüzden çalışan/emekli oranı sistemin dengesini belirler.'),
  ('Nüfusun yaşlanması dağıtım esaslı emeklilik sistemlerini neden zorlar?', 'Prim ödeyen çalışan başına düşen emekli sayısı artar', ['Yaşlı nüfus hiç tüketim yapmaz', 'Emekli aylıkları yaşlanan nüfusla birlikte yasa gereği kendiliğinden ve otomatik olarak düşer', 'Genç nüfus prim ödemekten muaf tutulur'], 'Çalışan sayısı emekli sayısına göre azaldıkça toplanan primler aylıkları karşılamakta yetersiz kalır; açık bütçeden kapatılmak zorunda kalınır.'),
  ('Emekliliğe 30 yıl kalan biri ile 2 yıl kalan biri için emeklilik fonu dağılımı konusunda en doğru değerlendirme hangisidir?', 'Emekliliğe yakın olan, oynaklığı düşük varlıklara daha çok ağırlık vermelidir', ['İkisi de yaşlarına bakmadan bütün birikimi aynı yüksek riskli hisse senedi fonunda tutmalıdır', 'Emekliliğe yakın olan daha yüksek riskli varlıklara yönelmelidir', 'Uzun vadeli olan yalnızca nakit tutmalıdır'], 'Uzun vadeli yatırımcı dalgalanmaları telafi edecek zamana sahiptir; emekliliğe yaklaşan kişide büyük bir düşüş telafi edilemeyebileceği için risk azaltılır.'),
  ('Emeklilik planlamasında enflasyonun hesaba katılmaması hangi hataya yol açar?', 'Gelecekteki giderlerin olduğundan düşük tahmin edilmesine', ['Birikimin reel değerinin kesinlikle artmasına', 'Emeklilik yaşının yasal olarak düşmesine ve aylıkların kendiliğinden artmasına', 'Faiz gelirlerinin vergiden muaf olmasına'], 'Bugünkü fiyatlarla yapılan bir hesap, onlarca yıl sonraki fiyat düzeyini yansıtmaz; hedef birikim reel olarak yetersiz kalır.'),
  ('Geliri Türk lirası olan bir kişinin döviz cinsinden kredi kullanmasının temel riski hangisidir?', 'Kur yükselirse lira cinsinden borç yükü artar', ['Kur yükselince borç kendiliğinden silinir', 'Döviz kredisinin hiçbir faizi olmaz', 'Kur hareketleri yalnızca ihracatçıları etkiler, borçluları hiçbir biçimde etkilemez'], 'Geliri ile borcu farklı para biriminde olan kişi kur riski taşır; yerli para değer kaybederse aynı döviz taksidini ödemek için daha çok lira gerekir.'),
  ('Yurt dışında üniversite okumayı planlayan ve masrafları avro olacak bir aile için kur riskini azaltmanın mantıklı yolu hangisidir?', 'Birikimin bir kısmını zaman içinde avro olarak biriktirmek', ['Bütün birikimi tek seferde kaldıraçlı kripto işlemine yatırmak', 'Masrafı hiç planlamayıp son ay kredi çekmek', 'Birikimi tamamen nakit lira olarak evde tutmak'], 'Gideri avro olan biri, birikimini kademeli olarak aynı para biriminde tutarak gelecekteki kur hareketlerinin etkisini dengeleyebilir.'),
  ('Bitcoin protokolüne göre üretilebilecek azami Bitcoin miktarı yaklaşık kaç milyondur?', '21', ['100', '50', '18,5'], 'Bitcoin\'in arzı protokolle 21 milyon adetle sınırlandırılmıştır; bu kıtlık tasarımın temel özelliklerinden biridir.'),
  ('Blokzincir teknolojisinin temel özelliği en doğru biçimde hangisidir?', 'İşlemlerin dağıtık ve değiştirilmesi zor bir kayıt defterinde tutulması', ['Bütün işlemlerin tek bir merkez bankasının sunucusunda saklanması', 'Kayıtların istendiği zaman tek kişi tarafından silinebilmesi', 'İşlemlerin yalnızca kâğıt defterlere yazılıp bir noterde saklanması zorunluluğu'], 'Blokzincirde işlemler bloklar hâlinde birbirine kriptografik olarak bağlanır ve çok sayıda bilgisayarda kopyalanır; geçmişi değiştirmek çok zordur.'),
  ('Merkez bankası dijital parasını (CBDC) Bitcoin gibi kripto paralardan ayıran temel özellik hangisidir?', 'Bir merkez bankasının yükümlülüğü olması', ['Arzının matematiksel olarak 21 milyonla sınırlı olması', 'Hiçbir kurum tarafından çıkarılmaması', 'Değerinin tamamen madencilik maliyetine bağlı olması'], 'CBDC, ulusal paranın dijital biçimidir ve merkez bankasınca çıkarılır; kripto paraların çoğunda ise merkezi bir ihraççı yoktur.'),
  ('Bir kripto paranın fiyatının bir haftada yüzde 60 düşüp ertesi ay yüzde 80 artması bu varlığın paranın hangi işlevini yerine getirmekte zorlandığını gösterir?', 'Hesap birimi ve değer saklama', ['Yalnızca değişim aracı olma', 'Ertelenmiş ödeme ve kredi notu', 'Bileşik faiz ve kupon ödeme'], 'Değeri sert dalgalanan bir varlıkla fiyat ifade etmek ve servet saklamak zordur; bu, para olarak kullanılmasının önündeki temel engellerden biridir.'),
  ('Saadet zinciri (piramit düzeni) için hangisi doğrudur?', 'Kazanç büyük ölçüde yeni üye getirmeye dayanır', ['Kazanç ağırlıkla gerçek ürün satışından gelir', 'Bütün katılımcıların kâr etmesi matematiksel olarak garantidir', 'Devletin denetlediği yasal bir yatırım fonudur'], 'Piramit düzenlerinde gelir yeni üyelerin giriş ücretlerinden oluşur; üye bulmak giderek imkânsızlaştığı için alt katmanlardakilerin çoğu kaybeder.'),
  ('Bir internet sitesinden alışveriş yapmadan önce sitenin güvenilirliğini kontrol etmek için yapılacak en uygun adım hangisidir?', 'Adresi ve satıcı bilgilerini doğrulamak', ['Sitenin renklerinin canlı olup olmadığına bakmak', 'Fiyat çok ucuzsa hemen ödeme yapmak', 'Kart bilgilerini e-postayla satıcıya göndermek'], 'Alan adının doğru yazıldığı, güvenli bağlantı kullanıldığı ve satıcının iletişim bilgilerinin gerçek olduğu kontrol edilmelidir; aşırı ucuz fiyatlar uyarı işaretidir.'),
  ('Hesap güvenliği için iki aşamalı doğrulamanın (şifre ve telefona gelen kod) kullanılması neden önerilir?', 'Şifre çalınsa bile ikinci adım olmadan giriş zorlaşır', ['Şifre kullanmayı tamamen gereksiz kılar', 'Bankanın vadesiz hesaba ödediği faiz oranını kendiliğinden artırır', 'Kart limitini otomatik olarak iki katına çıkarır'], 'İki aşamalı doğrulamada saldırganın hem şifreyi hem de kullanıcının cihazını ele geçirmesi gerekir; bu, hesabın ele geçirilmesini önemli ölçüde zorlaştırır.'),
  ('Tanımadığı biri sosyal medyadan yazıp "hesabına yatırılacak parayı başka hesaba aktarırsan komisyon alırsın" diyor. Bu teklifi kabul etmenin en büyük riski nedir?', 'Yasa dışı para transferine aracı olarak cezai sorumluluk', ['Bankanın ona yıllık ek faiz ödemesi', 'Kredi notunun kesinlikle yükselmesi', 'Hesabının banka tarafından otomatik olarak döviz tevdiat hesabına dönüştürülmesi'], 'Bu düzende kişinin hesabı dolandırıcılıktan elde edilen paranın aklanmasında kullanılır; hesap sahibi suça ortak sayılabilir.'),
  ('Bir yatırımcı, aldığı fiyatın altına düşen hissesini "zararına satmam" diyerek yıllarca elde tutuyor, kâr eden hisselerini ise hemen satıyor. Bu davranış neye örnektir?', 'Elden çıkarma etkisi', ['Çeşitlendirme ilkesi', 'Bileşik faiz etkisi', 'Etkin piyasa davranışı ve rasyonel beklenti'], 'Elden çıkarma (disposition) etkisi, kazandıran varlıkları erken satıp kaybettirenleri uzun süre tutma eğilimidir; kayıptan kaçınmayla ilişkilidir.'),
  ('Herkesin bir hisseye koştuğunu görüp şirketi incelemeden aynı hisseyi almak hangi davranışsal eğilime örnektir?', 'Sürü davranışı', ['Zihinsel muhasebe', 'Kayıptan kaçınma', 'Sahiplik etkisi ve değer biçme'], 'Sürü davranışında kişiler kendi analizleri yerine kalabalığı takip eder; bu eğilim balonların oluşmasına katkı yapabilir.'),
  ('Bir öğrencinin piyangodan kazandığı parayı "nasılsa çantada keklikti" diyerek kolayca harcarken maaşını özenle kullanması hangi kavramla açıklanır?', 'Zihinsel muhasebe', ['Bileşik faiz', 'Çeşitlendirme', 'Risk primi ve getiri dengesi'], 'Zihinsel muhasebede insanlar parayı kaynağına göre farklı kutulara koyar; oysa ekonomik açıdan bir lira her yerde bir liradır.'),
  ('Yatırımcıların kendi bilgi ve öngörü yeteneklerini olduğundan yüksek görmeleri sonucu çok sık alım satım yapmalarına neden olan önyargı hangisidir?', 'Aşırı güven', ['Kayıptan kaçınma', 'Statüko yanlılığı', 'Varsayılan seçenek ve hazır plan etkisi'], 'Aşırı güvenen yatırımcılar piyasayı yenebileceklerine inanır; sık işlem masrafları ise getirilerini genellikle düşürür.'),
  ('Davranışsal ekonomiye katkılarıyla 2017 Nobel Ekonomi Ödülü\'nü alan ve "dürtme" (nudge) kavramıyla tanınan iktisatçı kimdir?', 'Richard Thaler', ['Daniel Kahneman', 'Robert Shiller', 'Eugene Fama'], 'Richard Thaler 2017\'de Nobel aldı; Cass Sunstein ile birlikte yazdığı "Nudge" kitabıyla dürtme kavramını yaygınlaştırdı.'),
  ('Bir kişi kendi eşyasını satarken, aynı eşyayı satın almak için ödeyeceğinden çok daha yüksek fiyat istiyor. Bu davranış neyle açıklanır?', 'Sahiplik etkisi', ['Paranın dolaşım hızı', 'Ölçek ekonomisi', 'Bileşik faiz ve vade etkisi'], 'Sahiplik etkisinde insanlar sahip oldukları şeye, sırf onlara ait olduğu için daha yüksek değer biçer.'),
  ('Türkiye\'de tüketici kredisi sözleşmelerinde tüketiciye gerekçe göstermeden sözleşmeden cayma hakkı kaç gün içinde tanınmıştır?', '14', ['3', '7', '10'], '6502 sayılı Tüketicinin Korunması Hakkında Kanun\'a göre tüketici, kredi sözleşmesinden 14 gün içinde gerekçe göstermeden cayabilir.'),
  ('Bir kredi teklifinde aylık faiz oranı düşük görünse de dosya masrafı ve zorunlu sigorta gibi ek ödemeler varsa kredileri karşılaştırmanın en doğru yolu hangisidir?', 'Toplam geri ödeme tutarına ve yıllık maliyet oranına bakmak', ['Yalnızca reklamdaki aylık faiz oranına bakmak', 'Bankanın tabelasının büyüklüğüne ve şube sayısına bakarak karar vermek', 'En kısa sürede onay veren bankayı seçmek'], 'Ek ödemeler kredinin gerçek maliyetini yükseltir; toplam geri ödeme ve yıllık maliyet oranı farklı teklifleri adil biçimde karşılaştırmayı sağlar.'),
  ('"Sıfır faiz, 12 taksit" kampanyasında ürünün peşin fiyatı taksitli fiyattan yüzde 15 ucuzsa en doğru değerlendirme hangisidir?', 'Taksitli seçeneğin gizli bir finansman maliyeti vardır', ['Kampanya kesinlikle maliyetsizdir', 'Peşin fiyat ile taksitli fiyat aynı şeydir', 'Taksitli alışveriş, faiz yazmadığı sürece her zaman peşin alışverişten ucuzdur'], 'Peşin alana yapılan indirim, taksitli fiyata gömülmüş bir faiz gibidir; peşin ödeme imkânı varsa bu fark finansman maliyeti olarak değerlendirilmelidir.'),
  ('Tüketicinin, kredi sözleşmesi imzalanmadan önce bankadan alma hakkı olan ve kredinin bütün koşullarını gösteren belgeye ne ad verilir?', 'Sözleşme öncesi bilgi formu', ['Hesap kesim ekstresi', 'Temettü bildirimi', 'Bankanın yıllık gelir tablosu ve bilançosu'], 'Sözleşme öncesi bilgi formu, faiz, masraf, toplam maliyet ve ödeme planı gibi temel koşulları tüketiciye önceden göstererek bilinçli karar vermesini sağlar.'),
  ('İnternette "tıklayın, ön onaylı krediniz hazır" yazan bir reklamla karşılaşan biri için en doğru tutum hangisidir?', 'Teklifi bankanın resmî kanalından doğrulamak', ['Bağlantıya tıklayıp kimlik bilgilerini girmek', 'Reklam ön onay dediği için hemen ücret yatırmak', 'Kart şifresini reklamdaki forma yazmak'], 'Sahte kredi reklamları kişisel bilgi ve ön ödeme toplamak için kullanılır; gerçek teklifler bankanın resmî uygulama ya da şubesinden doğrulanabilir.'),
  ('"Paranın uzun dönemde yansız olduğu" görüşü neyi savunur?', 'Para miktarı uzun vadede yalnızca nominal değişkenleri etkiler', ['Para miktarı arttıkça reel üretim de sonsuza kadar artar', 'Para miktarının fiyatlar ve ücretlerle hiçbir dönemde ve hiçbir biçimde ilişkisi yoktur', 'Paranın değeri yalnızca altına göre belirlenir'], 'Yansızlık görüşüne göre para arzındaki değişim uzun vadede fiyatlar ve ücretler gibi nominal büyüklüklere yansır; reel üretim ve istihdam ise teknoloji ve kaynaklarla belirlenir.'),
  ('Bir bankanın elindeki menkul kıymeti, belirli bir süre sonra geri almak üzere satarak kısa vadeli borçlanmasına ne ad verilir?', 'Repo', ['Temettü', 'Halka arz', 'Bedelsiz sermaye artırımı'], 'Repoda taraf menkul kıymeti satar ve ileri bir tarihte geri almayı taahhüt eder; ekonomik olarak bu, teminatlı kısa vadeli borçlanmadır.'),
  ('Faiz artışının ulusal paraya değer kazandırarak enflasyonu düşürmesi hangi aktarım kanalına örnektir?', 'Döviz kuru kanalı', ['Servet kanalı', 'Vergi kanalı', 'Kamu harcaması ve bütçe kanalı'], 'Faiz artışı yerli parayı cazip kılar, kur düşer; ithal mallar ucuzlayınca yurt içi fiyat artışları yavaşlar.'),
  ('Bankaların birbirlerine kısa vadeli, genellikle gecelik borç verdikleri piyasaya ne ad verilir?', 'Bankalararası para piyasası', ['Hisse senedi birincil piyasası', 'Emtia vadeli işlem piyasası', 'Gayrimenkul ve konut piyasası'], 'Fazla likiditesi olan bankalar, açığı olan bankalara bankalararası para piyasasında kısa vadeli borç verir; bu piyasanın faizi para politikasının yakından izlediği bir göstergedir.'),
  ('Müşterinin izniyle banka hesap bilgilerinin güvenli bir arayüzle başka finans uygulamalarıyla paylaşılmasına dayanan yaklaşım hangisidir?', 'Açık bankacılık', ['Gölge bankacılık', 'Kaldıraçlı bankacılık', 'Kısmi rezerv ve karşılık bankacılığı'], 'Açık bankacılıkta müşteri onayıyla hesap verileri uygulama programlama arayüzleri üzerinden yetkili üçüncü taraflarla paylaşılır; bu, rekabeti ve yeni hizmetleri artırır.'),
  ('Bir ürünün fiyatı aynı kalırken ambalajındaki miktarın azaltılması enflasyon ölçümü açısından nasıl değerlendirilmelidir?', 'Birim fiyat arttığı için gizli bir fiyat artışıdır', ['Fiyat değişmediği için enflasyonu hiç etkilemez', 'Ürün ucuzladığı için deflasyon yaratır', 'Yalnızca ihracat fiyatlarını etkiler, yurt içi tüketici fiyatlarına hiçbir etkisi olmaz'], 'Aynı paraya daha az ürün almak birim fiyatın yükselmesi demektir; bu "küçülen paket" uygulaması ölçümde birim fiyat üzerinden dikkate alınmalıdır.'),
  ('Maaşların ya da kiraların geçmiş enflasyon oranına göre otomatik artırılması uygulamasına ne ad verilir?', 'Endeksleme', ['Sterilizasyon', 'Senyoraj', 'Arbitraj ve fiyat eşitleme'], 'Endekslemede ödemeler bir fiyat endeksine bağlanır; satın alma gücünü korur ama geçmiş enflasyonun geleceğe taşınmasına da yol açabilir.'),
  ('Bir hanenin finansal durumunu belirli bir tarihte, varlıklar ve borçlar açısından gösteren tabloya ne ad verilir?', 'Kişisel bilanço', ['Nakit akış tablosu', 'Kredi kartı ekstresi', 'Aylık harcama günlüğü ve fiş listesi'], 'Kişisel bilanço belirli bir andaki varlıkları, borçları ve aradaki farkı (net değeri) gösterir; nakit akış tablosu ise bir dönemdeki giriş ve çıkışları izler.'),
  ('Sevgi\'nin aylık geliri gideri karşılıyor ama net değeri her yıl düşüyor. Bu durumun en olası açıklaması hangisidir?', 'Varlıklarının değer kaybetmesi ya da borçlarının artması', ['Gelirinin her ay artması', 'Birikim hesabının her ay düzenli olarak faiz getirmesi ve büyümesi', 'Hiç borcunun olmaması'], 'Net değer varlıklarla borçlar arasındaki farktır; gelir-gider dengesi olsa bile değer kaybeden varlıklar ya da artan borçlar net değeri düşürebilir.'),
  ('2.000.000 liralık bir ev için 1.500.000 lira konut kredisi kullanan birinin kredi/değer oranı yüzde kaçtır?', '75', ['25', '50', '133,3'], 'Kredi/değer oranı = kredi / ev değeri = 1.500.000 / 2.000.000 = 0,75; yani yüzde 75. Peşinat ise yüzde 25\'tir.'),
  ('Konut kredilerinde kredi/değer oranına üst sınır konulmasının finansal istikrar açısından amacı nedir?', 'Konut fiyatları düşerse borçların teminat değerini aşmasını önlemek', ['Bankaların hiç konut kredisi vermemesini sağlamak', 'Konut fiyatlarının her yıl en az iki katına çıkmasını yasal düzenlemeyle güvence altına almak', 'Peşinatsız ev alımını zorunlu hâle getirmek'], 'Yüksek peşinat bir güvenlik payı yaratır; ev fiyatları düşse bile borç teminatın altında kalır ve bankaların zarar riski azalır.'),
  ('Borsada "limit emir" ile "piyasa emri" arasındaki fark hangisidir?', 'Limit emirde alım ya da satım fiyatı yatırımcı tarafından belirlenir', ['Limit emir yalnızca tahviller için verilebilir', 'Piyasa emri yalnızca seans kapanışından sonra ve ertesi günün açılış fiyatıyla gerçekleşir', 'Limit emirler her zaman anında gerçekleşir'], 'Piyasa emri o anki en iyi fiyattan hemen gerçekleşir; limit emir ise ancak belirlenen fiyata ya da daha iyisine ulaşıldığında çalışır.'),
  ('Bir yatırımcıya belirli bir varlığı önceden belirlenen fiyattan belirli bir tarihe kadar satın alma hakkı veren türev araca ne ad verilir?', 'Alım opsiyonu', ['Satım opsiyonu', 'Kuponsuz tahvil', 'Döviz tevdiat hesabı'], 'Alım opsiyonu sahibine hak verir ama yükümlülük getirmez; fiyat kullanım fiyatının üzerine çıkarsa hak kullanılır, çıkmazsa yalnızca ödenen prim kaybedilir.'),
  ('Ön ödemeli kartlara ya da dijital cüzdanlara yüklenen ve karşılığında fon alınarak çıkarılan parasal değere ne ad verilir?', 'Elektronik para', ['Mal para', 'Hatıra parası', 'Kaydi olmayan altın sikke ve madalya'], 'Elektronik para, karşılığı önceden ödenerek çıkarılan ve elektronik ortamda saklanan parasal değerdir; ödeme ve elektronik para kuruluşları tarafından ihraç edilir.'),
  ('Türkiye\'de madeni paraları basan kurum hangisidir?', 'Darphane ve Damga Matbaası', ['TCMB Banknot Matbaası', 'Borsa İstanbul', 'Türkiye İstatistik Kurumu ve Hazine'], 'Banknotlar TCMB Banknot Matbaasında basılırken madeni paralar Darphane ve Damga Matbaası Genel Müdürlüğü tarafından üretilir.'),
  ('İnternet alışverişinde kart sahibine telefonuna gelen tek kullanımlık şifreyle ödemeyi onaylatan güvenlik protokolü genellikle hangi adla bilinir?', '3D Secure', ['IBAN', 'SWIFT', 'FAST ve EFT sistemi'], '3D Secure, çevrim içi kart ödemelerinde kart sahibinin ek bir doğrulamayla kimliğini kanıtlamasını sağlar; izinsiz kullanımı zorlaştırır.'),
  ('İnternet alışverişlerinde sık kullanılan "sanal kart" için en doğru güvenlik avantajı hangisidir?', 'Limiti ayrıca belirlenerek riski sınırlandırır', ['Hiçbir şifre gerektirmeden kullanılır', 'Harcamaları otomatik olarak faizsiz taksitlendirir', 'Kart borcunu banka yerine devlet öder'], 'Sanal kart, fiziki karttan ayrı bir numara ve kullanıcının belirlediği düşük limitle çalışır; bilgiler çalınsa bile olası kayıp sınırlı kalır.'),
  ('Kredi kartının arkasında bulunan ve internet alışverişlerinde istenen üç haneli güvenlik koduna ne ad verilir?', 'CVV', ['IBAN kontrol hanesi', 'SWIFT kodu', 'Müşteri numarası ve şube kodu'], 'CVV/CVC kodu kartın fiziken elde olduğunu doğrulamaya yarar; bu kod hiç kimseyle paylaşılmamalıdır.'),
  ('Gerçek değeri 500.000 lira olan bir araba 800.000 liraya sigortalanırsa tam hasar durumunda sigortalının alabileceği tazminat için hangisi doğrudur?', 'Gerçek zarar olan 500.000 lirayla sınırlıdır', ['Sigorta bedeli olan 800.000 lirayı alır', 'İkisinin toplamı olan 1.300.000 lirayı alır', 'Aşkın sigorta yapıldığı için hiçbir tazminat alamaz'], 'Sigorta zenginleşme aracı değildir; aşkın sigortada tazminat gerçek zararla sınırlıdır ve fazla prim ödenmiş olur.'),
  ('Özel sağlık sigortalarında sigortalının her muayene ya da tedavide giderin belirli bir kısmını kendisinin ödemesine ne ad verilir?', 'Katılım payı', ['Rücu hakkı', 'İştira', 'Prim iadesi ve ikramiye'], 'Katılım payı (eş ödeme), giderin bir kısmının sigortalıda kalmasını sağlar; gereksiz kullanımı azaltır ve primi düşürür.'),
  ('Sosyal güvencesi bulunan birinin, özel hastanelerdeki fark ücretlerini karşılamak için yaptırdığı sigorta türü hangisidir?', 'Tamamlayıcı sağlık sigortası', ['Zorunlu trafik sigortası', 'Konut sigortası', 'Ferdi kaza ve hayat sigortası'], 'Tamamlayıcı sağlık sigortası, sosyal güvenlik kurumunun anlaşmalı özel hastanelerde kalan fark ücretlerini karşılamak için tasarlanmıştır.'),
  ('Katılım finansında faiz yerine kira ya da kâr payı esasıyla ihraç edilen menkul kıymetlere Türkiye\'de ne ad verilir?', 'Kira sertifikası', ['Varant', 'Kuponsuz devlet tahvili', 'Hazine bonosu ve ters repo sözleşmesi'], 'Kira sertifikaları bir varlığın gelirine dayanır ve yatırımcıya faiz yerine kira geliri ya da kâr payı öder.'),
  ('Bir endeksin piyasa değeri ağırlıklı hesaplanması ne anlama gelir?', 'Büyük şirketlerin fiyat hareketleri endeksi daha çok etkiler', ['Bütün şirketler endeksi eşit ölçüde etkiler', 'Yalnızca en küçük şirket dikkate alınır', 'Endeks yalnızca son yıl temettü dağıtan şirketleri kapsar ve fiyatlara bakmaz'], 'Piyasa değeri ağırlıklı endekste her şirketin etkisi toplam piyasa değerindeki payıyla orantılıdır; dev şirketlerdeki küçük hareketler endeksi belirgin biçimde oynatır.'),
  ('Her biri benzersiz olan ve birbirinin yerine geçemeyen dijital varlık belgelerine ne ad verilir?', 'NFT', ['Sabit koin', 'Merkez bankası dijital parası', 'Kuponsuz tahvil ve bono'], 'NFT\'ler birbirinin yerine geçemeyen tokenlardır; bir Bitcoin başka bir Bitcoin\'e eşdeğerken her NFT kendine özgüdür.'),
  ('Bir kripto borsasının iflas etmesiyle kullanıcıların varlıklarına erişememesi hangi riskin somut örneğidir?', 'Karşı taraf (saklama) riski', ['Enflasyon riski', 'Kur riski', 'Faiz oranı ve tahvil vadesi riski'], 'Varlıklar borsada saklandığında kullanıcı aslında borsanın ödeme gücüne güvenir; borsa batarsa varlıklara ulaşmak mümkün olmayabilir.'),
  ('Bir yatırımcının borsadaki düşüşten sonra "zaten düşeceği belliydi" demesi hangi önyargıya örnektir?', 'Geriye dönük bakış yanılgısı', ['Çapalama', 'Zihinsel muhasebe', 'Şimdiki zaman yanlılığı ve aceleci tüketim'], 'Olay gerçekleştikten sonra onun önceden öngörülebilir olduğunu sanmak geriye dönük bakış yanılgısıdır; aşırı güvene zemin hazırlar.'),
  ('Politika faizindeki artış genellikle mevduat faizlerini de yükseltir. Bunun hanehalkı davranışına beklenen etkisi hangisidir?', 'Tasarruf etmek daha cazip hâle gelir', ['Bugün harcama yapmak daha cazip hâle gelir', 'Kredi kullanmak daha ucuzlar', 'Tasarruf yapmanın getirisi azalır'], 'Yüksek mevduat faizi bugünkü tüketimin fırsat maliyetini artırır; bu da tasarrufu teşvik edip harcamaları yavaşlatır.'),
  ('Yüksek enflasyonun ekonomide fiyat sinyallerini bozması ne anlama gelir?', 'Göreli fiyat değişimlerini genel artıştan ayırmak zorlaşır', ['Bütün fiyatlar tam olarak aynı oranda artar', 'Fiyatlar artık hiçbir bilgi taşımaz ve mağazalarda yasal olarak ilan edilmez', 'Üreticiler fiyat belirlemeyi tamamen bırakır'], 'Her şey hızla pahalanırken bir malın gerçekten kıtlaşıp kıtlaşmadığını anlamak zorlaşır; bu da kaynakların yanlış dağıtılmasına yol açar.'),
  ('Reel faizin negatif olduğu bir ortamda hanehalkı ve firmaların davranışında hangi eğilim beklenir?', 'Borçlanma ve harcama teşvik edilir', ['Tasarruf etmek çok daha cazip hâle gelir', 'Kredi talebi tamamen ortadan kalkar', 'Bankalar kredi vermeyi yasal olarak durdurur'], 'Reel faiz negatifse borcun reel maliyeti düşüktür, mevduat ise reel kaybettirir; bu da borçlanmayı ve harcamayı özendirir.'),
  ('Faiz oranlarının yükselmesi firmaların yeni fabrika ve makine yatırımlarını nasıl etkiler?', 'Finansman maliyeti arttığı için yatırım azalır', ['Yatırımlar kesinlikle iki katına çıkar', 'Yatırım kararları faizden etkilenmez', 'Firmalar yatırımı artırmak için yalnızca daha çok borçlanır'], 'Yatırımlar çoğunlukla borçla finanse edilir; faiz yükselince projelerin getirisi finansman maliyetini karşılamakta zorlanır ve bazı yatırımlar ertelenir.'),
  ('Bir bankanın kredi başvurusunu değerlendirirken başvuranın aylık gelirine ve mevcut borç taksitlerine bakmasının temel amacı nedir?', 'Ödeme gücünü ölçmek', ['Başvuranın yaşını belirlemek', 'Kredi faizini sıfırlamak', 'Başvuranın eğitim düzeyini öğrenmek'], 'Gelire göre taksit yükü, başvuranın yeni taksidi ödemeye gücünün yetip yetmeyeceğini gösterir; banka riskini buna göre değerlendirir.'),
  ('Kredi kartlarındaki puan ve mil programları tüketici davranışı açısından nasıl değerlendirilmelidir?', 'Fazla harcamayı teşvik edebilir', ['Kart borcunun faizini her zaman sıfırlar', 'Kredi notunu kesin olarak yükseltir', 'Kartın yıllık ücretini yasal olarak kaldırır'], 'Ödül programları harcamayı özendirir; borcu tam ödemeyen biri için kazanılan puanlar ödenen faizin yanında çoğu zaman önemsiz kalır.'),
  ('Bir ülkede fiyat endeksi 10 yılda 100\'den 400\'e çıkmıştır. 10 yıl önceki 1 liranın satın alma gücü bugünkü paranın kaç lirasına denktir?', '4', ['0,25', '2,5', '40'], 'Fiyatlar 4 katına çıktığı için 10 yıl önceki 1 liranın aldığını almak için bugün 4 lira gerekir; tersinden bakıldığında bugünkü 1 lira o zamanki 0,25 liradır.'),
  ('50.000 lira yıllık yüzde 20 bileşik faizle kaç yılda 72.000 liraya ulaşır?', '2', ['3', '2,5', '4'], '50.000 · 1,2 = 60.000; 60.000 · 1,2 = 72.000. Yani 2 yıl gerekir.'),
  ('Yıllık yüzde 60 basit faiz oranı aylık basit orana çevrilirse yüzde kaç olur?', '5', ['6', '0,6', '12,5'], 'Basit faizde yıllık oran 12\'ye bölünür: 60 / 12 = yüzde 5.'),
  ('Bir şirketin kendi hisselerini piyasadan satın alması (geri alım) diğer koşullar sabitken hisse başına kârı nasıl etkiler?', 'Dolaşımdaki hisse azaldığı için artırır', ['Hisse sayısı arttığı için azaltır', 'Hisse başına kârı hiç etkilemez', 'Şirketin o yılki bütün kârını muhasebe kaydıyla sıfırlar'], 'Kâr aynı kalırken pay sayısı azalınca hisse başına kâr yükselir; geri alımlar bu yüzden hissedarlara değer aktarma yolu olarak kullanılır.'),
  ('Portföydeki varlıkların ağırlıkları zamanla hedeften saptığında belirli aralıklarla alım satım yaparak başlangıç oranlarına dönülmesine ne ad verilir?', 'Yeniden dengeleme', ['Açığa satış', 'Kaldıraç artırma', 'Temettü dağıtımı ve kâr payı'], 'Örneğin yüzde 60 hisse yüzde 40 tahvil hedefi hisse yükselişiyle yüzde 70\'e çıkarsa, bir kısım hisse satılıp tahvil alınarak risk düzeyi yeniden hedefe getirilir.'),
  ('Pratik bir kural olarak "100 eksi yaş" yöntemi portföydeki hisse senedi oranını önerir. 30 yaşındaki biri için bu kural hisse oranını yüzde kaç olarak verir?', '70', ['30', '50', '60'], '100 − 30 = 70; kural bu kişiye birikiminin yaklaşık yüzde 70\'ini hisseye ayırmasını önerir. Kesin bir yasa değil, kaba bir başlangıç noktasıdır.'),
  ('Aşağıdaki finansal hedeflerden hangisi ölçülebilir ve zamana bağlı olduğu için en iyi tanımlanmış olanıdır?', '18 ayda 36.000 lira acil durum fonu', ['Bir gün mutlaka zengin olmak', 'Daha az harcamaya çalışmak', 'Para konusunda bundan sonra daha dikkatli olmaya çalışmak'], 'İyi bir hedef belirli, ölçülebilir ve süreli olmalıdır; "18 ayda 36.000 lira" aylık 2.000 lira birikim planına dönüştürülebilir.'),
  ('Bir otomobil alırken yalnızca satış fiyatına bakmak yerine "toplam sahip olma maliyetini" hesaplamak neden önemlidir?', 'Yakıt, sigorta, bakım ve değer kaybı da maliyete eklenir', ['Satış fiyatı her zaman ve her araç için toplam sahip olma maliyetinden yüksektir', 'Toplam maliyet yalnızca kredi faizini kapsar', 'Araç sahibi olmanın hiçbir ek gideri yoktur'], 'Aracın yıllık yakıt, vergi, sigorta, bakım ve değer kaybı giderleri, satın alma kararını ve bütçeyi önemli ölçüde etkiler.'),
  ('Bir şehirde ev fiyatlarının yıllık kiraya oranı çok yüksektir. Bu durum kira mı ev almak mı kararında neyi düşündürür?', 'Kiralamak görece daha cazip olabilir', ['Ev almak kesinlikle daha kârlıdır', 'Kira ve ev alma maliyeti her durumda eşittir', 'Ev fiyatları kira gelirinden etkilenmez'], 'Fiyat/kira oranı yüksekse aynı konutu kiralamak satın almaya göre ucuz kalır; aradaki fark başka araçlarda değerlendirilebilir. Elbette kişisel koşullar da önemlidir.'),
  ('Bir kripto paranın blokzincirinde işlemlerin kimin tarafından doğrulandığı sorusuna en uygun yanıt hangisidir?', 'Ağa katılan dağıtık düğümler ve doğrulayıcılar', ['Ülkenin merkez bankası', 'Bir ticari bankanın genel müdürlüğü', 'Kripto parayı satın alan son kullanıcı ve onun bankası'], 'Merkezsiz ağlarda işlemler, ağa katılan çok sayıda düğüm tarafından uzlaşma kurallarıyla doğrulanır; merkezi bir otorite yoktur.'),
  ('Kargo şirketi adına gelen bir SMS\'te "gümrük ücreti için hemen bu bağlantıdan kart bilgilerinizi girin" deniyor. En doğru davranış hangisidir?', 'Bağlantıya tıklamadan resmî kanaldan kontrol etmek', ['Ücret küçük olduğu için hemen ödemek', 'Kart bilgilerini ve son kullanma tarihini SMS\'e yanıt olarak yazmak', 'Bağlantıyı arkadaşlarına da göndermek'], 'Bu tür mesajlar yaygın oltalama yöntemleridir; gönderi durumu yalnızca şirketin resmî sitesi ya da uygulamasından kontrol edilmelidir.'),
  ('Kısa vadeli ve düşük riskli borçlanma araçlarına yatırım yapan ve getirisi genellikle kısa vadeli faizlere yakın seyreden fon türü hangisidir?', 'Para piyasası fonu', ['Hisse senedi yoğun fon', 'Altın fonu', 'Serbest (hedge) fon ve türev'], 'Para piyasası fonları vadesi kısa bono, repo gibi araçlara yatırım yapar; oynaklığı düşüktür ve getiri kısa vadeli faizleri izler.'),
  ('FAST sisteminde IBAN yerine cep telefonu numarası, e-posta ya da T.C. kimlik numarasıyla para gönderilmesini sağlayan hizmetin adı nedir?', 'Kolay Adres', ['Hızlı Havale Ağı', 'Kolay Kart', 'Dijital Kimlik ve İmza'], 'Kolay Adres hizmetinde kişi bir tanımlayıcıyı hesabıyla eşleştirir; gönderen IBAN bilmeden bu tanımlayıcıyla transfer yapabilir.'),
  ('Türkiye Cumhuriyet Merkez Bankasının hukuki yapısı hangisidir?', 'Anonim şirket', ['Bakanlığa bağlı genel müdürlük', 'Belediye iştiraki', 'Kooperatif birliği'], 'TCMB kuruluşundan bu yana anonim şirket statüsündedir; hisseleri A, B, C ve D sınıflarına ayrılır ve A sınıfı hisseler Hazine\'ye aittir.'),
  ('Avro banknot ve madeni paraları hangi tarihte nakit olarak dolaşıma girmiştir?', '1 Ocak 2002', ['1 Ocak 1999', '1 Kasım 1993', '1 Ocak 2008'], 'Avro 1999\'da kaydi para olarak kullanılmaya başladı; banknot ve madeni paralar ise 1 Ocak 2002\'de dolaşıma girdi.'),
  ('Üzerindeki yazılı değer ile içerdiği değerli metalin değeri birbirine eşit olan paraya ne ad verilir?', 'Tam değerli para', ['İtibari para', 'Kaydi para', 'Elektronik para ve dijital cüzdan'], 'Eski altın ve gümüş sikkeler gibi metal değeri itibari değerine eşit olan paralar tam değerli paradır.'),
  ('Kredi kartı neden tam anlamıyla bir para türü sayılmaz?', 'Kartla yapılan ödeme aslında bankadan alınan bir borçtur', ['Kredi kartları yalnızca yurt dışındaki mağazalarda ve sitelerde geçerlidir', 'Kartla hiçbir mağazada ödeme yapılamaz', 'Kredi kartı devletin bastığı bir banknottur'], 'Kredi kartı bir ödeme ve borçlanma aracıdır; harcama anında banka adınıza ödeme yapar ve siz bu borcu daha sonra parayla kapatırsınız.'),
  ('Bankacılıkta "efektif" ile "döviz" arasındaki ayrım nedir?', 'Efektif nakit yabancı paradır, döviz ise yabancı paraya dayalı her türlü ödeme aracıdır', ['Efektif yalnızca külçe altını, döviz ise yalnızca gümüş sikkeleri ve madalyaları ifade eder', 'Efektif ile döviz arasında yalnızca yazım farkı vardır', 'Efektif yerli parayı, döviz yabancı parayı anlatır'], 'Efektif, elde tutulan yabancı banknotlardır; döviz ise yabancı para cinsinden hesaplar, çekler ve transferleri de kapsayan geniş bir kavramdır.'),
  ('Bankalarda fiziki altın teslim almadan altın cinsinden birikim yapılmasını sağlayan hesaba ne ad verilir?', 'Altın hesabı', ['Kredili mevduat hesabı', 'Döviz tevdiat hesabı', 'Bireysel emeklilik hesabı'], 'Altın hesabında birikim gram altın cinsinden tutulur; fiyat değişimleri hesabın lira karşılığını değiştirir.'),
  ('Faiz oranının sıfır olduğu bir ekonomide bir yıl sonra alınacak 1.000 liranın bugünkü değeri ne olur?', 'Tam bin lira', ['Sıfır lira', 'Dokuz yüz lira', 'Bin yüz lira'], 'Faiz sıfırsa iskonto uygulanmaz; bugünkü değer gelecekteki değere eşittir: 1.000 / (1 + 0) = 1.000 lira.'),
  ('Faizin neden pozitif olduğunu açıklayan "zaman tercihi" görüşü hangisini savunur?', 'İnsanlar tüketimi ertelemenin karşılığında bir ödül ister', ['Faiz yalnızca devletin koyduğu bir vergidir', 'Paranın gelecekte daha değerli olacağı kesindir', 'Faizin bankacılık sistemi dışında hiçbir ekonomik gerekçesi ve karşılığı yoktur'], 'İnsanlar genellikle bugünkü tüketimi geleceğe tercih eder; parasını başkasına bırakan kişi bu bekleyişin bedeli olarak faiz talep eder.'),
  ('Hayat sigortasında sigortalının vefatı hâlinde tazminatın ödeneceği kişiye ne ad verilir?', 'Lehdar', ['Sigorta ettiren', 'Acente', 'Eksper'], 'Lehdar, poliçede tazminatı alacak kişi olarak belirlenen kişidir; sigorta ettirenle aynı kişi olmak zorunda değildir.'),
  ('Bir hasar meydana geldiğinde zararın miktarını ve nedenini inceleyip rapor hazırlayan uzmana ne ad verilir?', 'Eksper', ['Lehdar', 'Aktüer', 'Kredi kefili'], 'Sigorta eksperi hasarı yerinde inceleyerek tutarını ve nedenini tespit eder; şirket tazminatı bu rapora göre belirler.'),
  ('Bir hisse senedi yatırımcısının getirisi hangi iki kaynaktan oluşur?', 'Temettü ve fiyat artışı', ['Kupon ve anapara', 'Kira ve prim', 'Mevduat faizi ve yıllık vergi iadesi'], 'Hissedar şirketin dağıttığı temettüden ve hissenin fiyatının alış fiyatının üzerine çıkmasından kazanç elde eder.'),
  ('Sabit getirili bir devlet tahvilini vadeye kadar tutan yatırımcının, devletin ödeme yapacağını varsaysak bile karşılaşabileceği temel risk hangisidir?', 'Beklenenden yüksek enflasyon', ['Şirketin iflas etmesi', 'Hissenin temettü kesmesi', 'Kart limitinin düşmesi'], 'Nominal ödemeler sabit olduğundan beklenmeyen yüksek enflasyon tahvilin reel getirisini eritir; bu enflasyon riskidir.'),
  ('Bir yatırım fonunun yatırım stratejisini, risklerini ve ücretlerini açıklayan resmî belgeye ne ad verilir?', 'İzahname', ['Poliçe', 'Dekont', 'Kredi kartı ekstresi'], 'İzahname fonun hangi varlıklara yatırım yapacağını, risk düzeyini ve kesintilerini açıklar; yatırım öncesinde okunması önerilir.'),
  ('Bir bankanın güvenilirliği konusunda kaygı duyan mevduat sahibi için en doğru davranış hangisidir?', 'Resmî kaynaklardan bilgi alıp sigorta kapsamını öğrenmek', ['Söylentilere bakarak hemen bütün parayı nakit olarak çekmek', 'Sosyal medyadaki her habere güvenmek', 'Panikle başka müşterileri de uyarmak'], 'Doğrulanmamış söylentiler banka hücumuna yol açabilir; sigorta kapsamını ve resmî açıklamaları öğrenmek rasyonel karar vermeyi sağlar.'),
  ('İndirim döneminde "son 2 ürün kaldı" uyarısını gören birinin ihtiyacı olmadığı hâlde ürünü hemen alması hangi pazarlama etkisine yenik düşmesidir?', 'Kıtlık algısı', ['Bileşik faiz', 'Çeşitlendirme', 'Likidite primi'], 'Ürünün tükeneceği izlenimi, kaçırma korkusunu tetikler ve kişiyi düşünmeden satın almaya iter; bu kıtlık algısı yaratma tekniğidir.'),
  ('İnternetten satın alınan bir ürünü teslimden sonra gerekçe göstermeden iade etme hakkına ne ad verilir?', 'Cayma hakkı', ['Rücu hakkı', 'Rüçhan hakkı', 'İntifa hakkı'], 'Mesafeli satışlarda tüketici, kanunda belirtilen istisnalar dışında belirli süre içinde gerekçe göstermeden cayma hakkını kullanabilir.'),
  ('Nakitsiz ödemelerin (kart, mobil ödeme) yaygınlaşmasının hanehalkı açısından olası bir dezavantajı hangisidir?', 'Harcamanın daha az hissedilmesi', ['Hiçbir kayıt tutulmaması', 'Paranın değerinin artması', 'Faizlerin kesinlikle sıfırlanması'], 'Nakit vermek harcamayı somut hissettirir; kartla ya da telefonla ödemede bu his zayıflar ve bütçe takip edilmezse aşırı harcama riski artar.'),
  ('Sahibine belirli bir dayanak varlığı önceden belirlenen fiyattan alma ya da satma hakkı veren ve genellikle aracı kurumlarca ihraç edilip borsada işlem gören menkul kıymete ne ad verilir?', 'Varant', ['Kira sertifikası ve sukuk', 'Döviz tevdiat hesabı', 'Hazine bonosu ve devlet tahvili'], 'Varant, opsiyona benzer biçimde hak verir ama yükümlülük getirmez; genellikle aracı kurumlar tarafından ihraç edilir ve borsada alınıp satılır.'),
  ('Vadeli işlem (futures) sözleşmesini opsiyondan ayıran temel özellik hangisidir?', 'İki tarafa da yükümlülük getirmesi', ['Yalnızca alıcıya hak tanıyıp satıcıya hiçbir yükümlülük getirmemesi', 'Hiçbir teminat gerektirmeden yalnızca bankalar arasında yapılabilmesi', 'Vadesi geldiğinde kendiliğinden hisse senedine dönüşmesi'], 'Vadeli işlemde alıcı da satıcı da vadede belirlenen fiyattan işlemi yapmakla yükümlüdür; opsiyonda ise alıcı hakkını kullanıp kullanmamakta serbesttir.'),
  ('Aynı varlığın iki farklı piyasada farklı fiyatlarla işlem görmesinden yararlanarak ucuz olandan alıp pahalı olana satmaya ne ad verilir?', 'Arbitraj', ['Kaldıraçlı spekülasyon ve açığa satış', 'Uzun vadeli değer yatırımcılığı', 'Portföyün yeniden dengelenmesi'], 'Arbitraj, fiyat farklarından neredeyse risksiz kazanç elde etmeye dayanır; arbitrajcıların işlemleri fiyat farkını hızla kapatır.'),
  ('Borçlunun belirli bir tarihte belirli bir tutarı alacaklıya ya da onun emrine ödeyeceğini taahhüt ettiği kambiyo senedine ne ad verilir?', 'Bono', ['Çek ve ödeme talimatı', 'Sigorta poliçesi', 'Hisse senedi ve temettü kuponu'], 'Bono, düzenleyenin bizzat ödeme vaadidir; çek ise düzenleyenin bankasına verdiği ödeme talimatıdır.'),
  ('Yasa dışı yollardan elde edilen paranın kaynağını gizleyip yasal kazanç gibi gösterilmesine ne ad verilir?', 'Kara para aklama', ['Senyoraj', 'Portföy yönetimi', 'Bankalararası repo işlemi'], 'Kara para aklamada suç gelirleri karmaşık işlemlerle finansal sisteme sokulur ve kaynağı gizlenir; bankalar bu nedenle müşterilerini tanıma ve şüpheli işlem bildirme yükümlülüğü taşır.'),
  ('Çeyrek, yarım ve tam Cumhuriyet altınları kaç ayar olarak basılır?', '22', ['24 ayar has altın olarak', '18', '14 ayar ve gümüş karışımı'], 'Cumhuriyet altınları 22 ayar olarak basılır; bu nedenle saf altın içerikleri ağırlıklarının yaklaşık yüzde 91,6\'sı kadardır.'),
  ('Katılım bankalarında vadeli birikimlerin değerlendirildiği ve sahibine faiz yerine kâr ya da zarara katılma esasıyla getiri sağlayan hesaba ne ad verilir?', 'Katılma hesabı', ['Kredili mevduat hesabı', 'Vadesiz tasarruf mevduatı', 'Döviz tevdiat ve repo hesabı'], 'Katılma hesabında getiri önceden sabitlenmez; bankanın bu fonlarla yaptığı işlemlerin kâr ya da zararına belirlenen oranlarda katılınır.'),
  ('Yüksek enflasyon dönemlerinde hanehalklarının gayrimenkul ve altın gibi reel varlıklara yönelmesinin temel nedeni nedir?', 'Parasal varlıkların satın alma gücü hızla eridiği için', ['Reel varlıkların hiçbir dönemde değer kaybetmemesi yasayla güvence altına alındığı için', 'Reel varlıklar her ay düzenli faiz ödediği için', 'Merkez bankası reel varlık alanlara doğrudan para ödediği için'], 'Nakit ve sabit getirili varlıkların değeri enflasyonla erirken reel varlıkların fiyatları genel fiyat düzeyiyle birlikte yükselme eğiliminde olduğu için koruma aracı olarak görülür.'),
];
